import{j as i}from"./vendor-react-DzFdt34V.js";import{f as $,C as m,l as f,b as x,d as y,g as v,U as j}from"./LabKit-lSa9lmSP.js";import{T as C,b as q,P as Z,r as E}from"./ProportionTools-C5bFAAln.js";import{p as I,a as P,c as w,g as B,b as A,P as D,C as R,d as M,e as U,D as K,S as T,I as L,f as H,h as S,i as F,j as O,k as G,l as Q,m as N,n as _,o as W,q as Y,r as u,s as V,t as J,u as X}from"./ProportionDbh2Tools-DDlm99dz.js";import{P as aa}from"./PairsMemoryGame-BsUueEbh.js";/* empty css              *//* empty css            */import{P as ea}from"./ProportionTool-ClppYOUZ.js";import{P as ta,D as oa,I as ra}from"./figures-R97wwwYD.js";import"./index-kdqHjeNF.js";import"./vendor-i18n-D_kkcOKx.js";import"./vendor-CAIZfmPq.js";import"./vendor-katex-CdCLdKXh.js";import"./plane-D_EM-YY5.js";import"./answers-CfNogv6P.js";import"./types-D0REvJHO.js";import"./figures-BsgLjgpW.js";import"./useLabText-BzgEu9JU.js";import"./notation-Ck7pSnFk.js";const a=(o,d,s)=>({eu:o,es:d,ar:s.replace(/\{,\}/g,".")}),t=o=>({eu:o,es:o,ar:o.replace(/\{,\}/g,".")}),c=o=>{const[d,s=""]=o.split(",");return $(Number(d+s),10**s.length)},r=o=>$(o),na=[{id:1401,prompt:a("Aurkitu $x$: $\\frac{4}{x}=\\frac{10}{25}$.","Halla $x$: $\\frac{4}{x}=\\frac{10}{25}$.","أوجد $x$: $\\frac{4}{x}=\\frac{10}{25}$."),options:[t("$10$"),t("$16$"),t("$62{,}5$")],correctIndex:0,explanation:t("$4\\cdot 25=10\\cdot x=100\\ \\to\\ x=10$"),topic:"proportion-review"},{id:1402,prompt:a("2 langilek 3 egunetan 12 m egiten dituzte. Zenbat metro egingo dituzte 4 langilek 3 egunetan?","2 obreros hacen 12 m en 3 días. ¿Cuántos metros harán 4 obreros en 3 días?","يُنجز عاملان 12 م في 3 أيام. كم مترًا يُنجز 4 عمال في 3 أيام؟"),options:[t("$48$"),t("$24$"),t("$6$")],correctIndex:1,explanation:a("Langile bikoitza, egun berak: metro bikoitza. $12\\cdot\\frac{4}{2}\\cdot\\frac{3}{3}=24$.","El doble de obreros, los mismos días: el doble de metros. $12\\cdot\\frac{4}{2}\\cdot\\frac{3}{3}=24$.","ضعف العمال بالأيام نفسها: ضعف الأمتار. $12\\cdot\\frac{4}{2}\\cdot\\frac{3}{3}=24$."),topic:"compound-direct"},{id:1403,prompt:a("4 langilek, egunean 6 ordu, 10 egun behar dituzte. Zenbat egun 6 langilek, egunean 5 ordu?","4 obreros, 6 horas al día, tardan 10 días. ¿Cuántos días tardan 6 obreros, 5 horas al día?","4 عمال يعملون 6 ساعات يوميًا يحتاجون 10 أيام. كم يومًا يحتاج 6 عمال يعملون 5 ساعات يوميًا؟"),options:[t("$12$"),t("$15$"),t("$8$")],correctIndex:2,explanation:a("Langile gehiago → egun gutxiago, eta ordu gutxiago → egun gehiago: biak alderantzizkoak. $10\\cdot\\frac{4}{6}\\cdot\\frac{6}{5}=8$.","Más obreros → menos días, y menos horas → más días: las dos inversas. $10\\cdot\\frac{4}{6}\\cdot\\frac{6}{5}=8$.","عمال أكثر ← أيام أقل، وساعات أقل ← أيام أكثر: كلاهما عكسي. $10\\cdot\\frac{4}{6}\\cdot\\frac{6}{5}=8$."),topic:"compound-mixed"},{id:1404,prompt:a("Banatu 60 zuzenki proportzionalki 1, 2 eta 3rekiko. Zenbat dagokio 3ri?","Reparte 60 de forma directamente proporcional a 1, 2 y 3. ¿Cuánto le toca al 3?","وزّع 60 طرديًا على 1 و2 و3. كم نصيب 3؟"),options:[t("$20$"),t("$30$"),t("$10$")],correctIndex:1,explanation:t("$60\\mathbin{:}(1+2+3)=10\\ \\to\\ 3\\cdot 10=30$"),topic:"direct-share"},{id:1405,prompt:a("Banatu 90 alderantziz proportzionalki 1 eta 2rekiko. Zenbat dagokio 1i?","Reparte 90 de forma inversamente proporcional a 1 y 2. ¿Cuánto le toca al 1?","وزّع 90 عكسيًا على 1 و2. كم نصيب 1؟"),options:[t("$60$"),t("$30$"),t("$45$")],correctIndex:0,explanation:a("Alderantzizkoak $\\frac{2}{2}$ eta $\\frac{1}{2}$: 2 eta 1ekiko. $90\\mathbin{:}3=30$, beraz $2\\cdot 30=60$.","Inversos $\\frac{2}{2}$ y $\\frac{1}{2}$: proporcional a 2 y 1. $90\\mathbin{:}3=30$, así que $2\\cdot 30=60$.","المقلوبان $\\frac{2}{2}$ و$\\frac{1}{2}$: متناسب مع 2 و1. $90\\mathbin{:}3=30$، إذن $2\\cdot 30=60$."),topic:"inverse-share"},{id:1406,prompt:a("$x$-ren % 20 8 da. Zenbat da $x$?","El 20 % de $x$ es 8. ¿Cuánto vale $x$?","20٪ من $x$ تساوي 8. كم قيمة $x$؟"),options:[t("$1{,}6$"),t("$160$"),t("$40$")],correctIndex:2,explanation:t("$x\\cdot 0{,}2=8\\ \\to\\ x=8\\mathbin{:}0{,}2=40$"),topic:"percent-total"},{id:1407,prompt:a("Prezio bat % 25 igotzen da. Zer zenbakiz biderkatzen da?","Un precio sube un 25 %. ¿Por qué número se multiplica?","يرتفع سعر بنسبة 25٪. في أي عدد يُضرب؟"),options:[t("$0{,}25$"),t("$1{,}25$"),t("$25$")],correctIndex:1,explanation:a("Igo ondoren % 125 da: $1{,}25$.","Después de subir es el 125 %: $1{,}25$.","بعد الزيادة يصبح 125٪: $1{,}25$."),topic:"index"},{id:1408,prompt:a("Prezio bat % 10 igo eta gero % 10 jaisten da. Amaierako prezioa…","Un precio sube un 10 % y luego baja un 10 %. El precio final es…","يرتفع سعر 10٪ ثم ينخفض 10٪. السعر النهائي…"),options:[a("hasierakoa bera","el mismo que el inicial","مثل الأصلي"),a("% 1 handiagoa","un 1 % mayor","أكبر بـ1٪"),a("% 1 txikiagoa","un 1 % menor","أصغر بـ1٪")],correctIndex:2,explanation:a("Indizeak biderkatu: $1{,}1\\cdot 0{,}9=0{,}99$, % 99: % 1 txikiagoa.","Se multiplican los índices: $1{,}1\\cdot 0{,}9=0{,}99$, el 99 %: un 1 % menor.","نضرب المؤشرين: $1{,}1\\cdot 0{,}9=0{,}99$، أي 99٪: أصغر بـ1٪."),topic:"chained"}],ia=[{id:1,stage:"proportions",prompt:a("Aurkitu $x$: $\\frac{6}{x}=\\frac{15}{40}$.","Halla $x$: $\\frac{6}{x}=\\frac{15}{40}$.","أوجد $x$: $\\frac{6}{x}=\\frac{15}{40}$."),expected:r(16),hint:a("Gurutzeko biderkadurak: $6\\cdot 40=15\\cdot x$.","Productos cruzados: $6\\cdot 40=15\\cdot x$.","الضرب التبادلي: $6\\cdot 40=15\\cdot x$."),explanation:t("$6\\cdot 40=15\\cdot x=240\\ \\to\\ x=240\\mathbin{:}15=16$")},{id:2,stage:"proportions",prompt:a("5 kg patatak $4{,}50$ € balio dute. Zenbat balio dute 12 kg-k?","5 kg de patatas cuestan $4{,}50$ €. ¿Cuánto cuestan 12 kg?","ثمن 5 كغ من البطاطا $4{,}50$ €. كم ثمن 12 كغ؟"),expected:c("10,8"),hint:a("Kilo batek: $4{,}50\\mathbin{:}5$.","Un kilo: $4{,}50\\mathbin{:}5$.","الكيلو الواحد: $4{,}50\\mathbin{:}5$."),explanation:t("$4{,}50\\mathbin{:}5=0{,}9\\ \\to\\ 0{,}9\\cdot 12=10{,}8$")},{id:3,stage:"proportions",prompt:a("8 txorrotak biltegi bat 6 orduan betetzen dute. Zenbat ordu beharko dituzte 12 txorrotak?","8 grifos llenan un depósito en 6 horas. ¿Cuántas horas tardarán 12 grifos?","8 صنابير تملأ خزانًا في 6 ساعات. كم ساعة تحتاج 12 صنبورًا؟"),expected:r(4),hint:a("Alderantzizkoa: biderkadura konstantea.","Inversa: el producto es constante.","عكسي: حاصل الضرب ثابت."),explanation:t("$8\\cdot 6=48\\ \\to\\ 48\\mathbin{:}12=4$")},{id:4,stage:"proportions",prompt:a("90 km/h-ra bidaia batek 4 ordu irauten du. Zenbat ordu 120 km/h-ra?","A 90 km/h un viaje dura 4 horas. ¿Cuántas horas a 120 km/h?","رحلة تستغرق 4 ساعات بسرعة 90 كم/س. كم ساعة بسرعة 120 كم/س؟"),expected:r(3),hint:a("Ibilbidea: $90\\cdot 4$.","El trayecto: $90\\cdot 4$.","المسار: $90\\cdot 4$."),explanation:t("$90\\cdot 4=360\\ \\to\\ 360\\mathbin{:}120=3$")},{id:5,stage:"compound",prompt:a("3 inprimagailuk 4 orduan 1200 orri inprimatzen dituzte. Zenbat orri 5 inprimagailuk 6 orduan?","3 impresoras imprimen 1200 hojas en 4 horas. ¿Cuántas hojas imprimen 5 impresoras en 6 horas?","3 طابعات تطبع 1200 ورقة في 4 ساعات. كم ورقة تطبع 5 طابعات في 6 ساعات؟"),expected:r(3e3),hint:a("Biak zuzenak: $\\frac{5}{3}$ eta $\\frac{6}{4}$.","Las dos directas: $\\frac{5}{3}$ y $\\frac{6}{4}$.","كلاهما طردي: $\\frac{5}{3}$ و$\\frac{6}{4}$."),explanation:t("$1200\\cdot\\frac{5}{3}\\cdot\\frac{6}{4}=3000$")},{id:6,stage:"compound",prompt:a("10 langilek, egunean 8 ordu, 15 egunetan bukatzen dute lan bat. Zenbat egun beharko dituzte 12 langilek, egunean 10 ordu?","10 obreros, 8 horas al día, terminan una obra en 15 días. ¿Cuántos días tardarán 12 obreros, 10 horas al día?","10 عمال يعملون 8 ساعات يوميًا ينهون عملًا في 15 يومًا. كم يومًا يحتاج 12 عاملًا يعملون 10 ساعات يوميًا؟"),expected:r(10),hint:a("Biak alderantzizkoak: $\\frac{10}{12}$ eta $\\frac{8}{10}$.","Las dos inversas: $\\frac{10}{12}$ y $\\frac{8}{10}$.","كلاهما عكسي: $\\frac{10}{12}$ و$\\frac{8}{10}$."),explanation:t("$15\\cdot\\frac{10}{12}\\cdot\\frac{8}{10}=10$")},{id:7,stage:"compound",prompt:a("5 behik 300 kg pentsu jaten dituzte 6 egunetan. 400 kg-rekin, zenbat egun elika daitezke 8 behi?","5 vacas comen 300 kg de pienso en 6 días. Con 400 kg, ¿cuántos días se pueden alimentar 8 vacas?","5 أبقار تأكل 300 كغ من العلف في 6 أيام. بـ400 كغ، كم يومًا يمكن إطعام 8 أبقار؟"),expected:r(5),hint:a("Pentsua zuzena, behiak alderantzizkoak.","El pienso, directa; las vacas, inversa.","العلف طردي والأبقار عكسي."),explanation:t("$6\\cdot\\frac{400}{300}\\cdot\\frac{5}{8}=5$")},{id:8,stage:"compound",prompt:a("4 lagunek 7 egunetan 280 € gastatzen dituzte. Zenbat gastatuko dute 6 lagunek 5 egunetan?","4 amigos gastan 280 € en 7 días. ¿Cuánto gastarán 6 amigos en 5 días?","4 أصدقاء ينفقون 280 € في 7 أيام. كم ينفق 6 أصدقاء في 5 أيام؟"),expected:r(300),hint:a("Lagun batek, egun batean.","Un amigo, en un día.","صديق واحد في يوم."),explanation:t("$280\\mathbin{:}4\\mathbin{:}7=10\\ \\to\\ 10\\cdot 6\\cdot 5=300$")},{id:9,stage:"shares",prompt:a("Banatu 360 zuzenki proportzionalki 3, 4 eta 5ekiko. Zenbat dagokio 5i?","Reparte 360 de forma directamente proporcional a 3, 4 y 5. ¿Cuánto le toca al 5?","وزّع 360 طرديًا على 3 و4 و5. كم نصيب 5؟"),expected:r(150),hint:a("$360\\mathbin{:}(3+4+5)$.","$360\\mathbin{:}(3+4+5)$.","$360\\mathbin{:}(3+4+5)$."),explanation:t("$360\\mathbin{:}12=30\\ \\to\\ 5\\cdot 30=150$")},{id:10,stage:"shares",prompt:a("Hiru bazkidek 2000 €, 3000 € eta 5000 € jarri zituzten, eta 1500 € irabazi dituzte. Zenbat dagokio 3000 € jarri zituenari?","Tres socios pusieron 2000 €, 3000 € y 5000 € y han ganado 1500 €. ¿Cuánto le toca al que puso 3000 €?","وضع ثلاثة شركاء 2000 € و3000 € و5000 € وربحوا 1500 €. كم نصيب من وضع 3000 €؟"),expected:r(450),hint:a("2, 3 eta 5ekiko banaketa.","Reparto proporcional a 2, 3 y 5.","توزيع متناسب مع 2 و3 و5."),explanation:t("$1500\\mathbin{:}(2+3+5)=150\\ \\to\\ 3\\cdot 150=450$")},{id:11,stage:"shares",prompt:a("Banatu 180 zuzenki proportzionalki $\\frac{1}{2}$ eta $\\frac{1}{4}$-rekiko. Zenbat dagokio $\\frac{1}{2}$-ri?","Reparte 180 de forma directamente proporcional a $\\frac{1}{2}$ y $\\frac{1}{4}$. ¿Cuánto le toca a $\\frac{1}{2}$?","وزّع 180 طرديًا على $\\frac{1}{2}$ و$\\frac{1}{4}$. كم نصيب $\\frac{1}{2}$؟"),expected:r(120),hint:a("$\\frac{2}{4}$ eta $\\frac{1}{4}$: 2 eta 1ekiko.","$\\frac{2}{4}$ y $\\frac{1}{4}$: proporcional a 2 y 1.","$\\frac{2}{4}$ و$\\frac{1}{4}$: متناسب مع 2 و1."),explanation:t("$180\\mathbin{:}(2+1)=60\\ \\to\\ 2\\cdot 60=120$")},{id:12,stage:"shares",prompt:a("Banatu 420 alderantziz proportzionalki 2 eta 5ekiko. Zenbat dagokio 2ri?","Reparte 420 de forma inversamente proporcional a 2 y 5. ¿Cuánto le toca al 2?","وزّع 420 عكسيًا على 2 و5. كم نصيب 2؟"),expected:r(300),hint:a("Alderantzizkoak: $\\frac{5}{10}$ eta $\\frac{2}{10}$, 5 eta 2rekiko.","Inversos: $\\frac{5}{10}$ y $\\frac{2}{10}$, proporcional a 5 y 2.","المقلوبان: $\\frac{5}{10}$ و$\\frac{2}{10}$، متناسب مع 5 و2."),explanation:t("$420\\mathbin{:}(5+2)=60\\ \\to\\ 5\\cdot 60=300$")},{id:13,stage:"percent",prompt:a("Kalkulatu 240ren % 35.","Calcula el 35 % de 240.","احسب 35٪ من 240."),expected:r(84),hint:a("% 35 = $0{,}35$.","35 % = $0{,}35$.","35٪ = $0{,}35$."),explanation:t("$240\\cdot 0{,}35=84$")},{id:14,stage:"percent",prompt:a("Kalkulatu 45en % 120.","Calcula el 120 % de 45.","احسب 120٪ من 45."),expected:r(54),hint:a("% 120 = $1{,}2$: kantitatea baino gehiago.","120 % = $1{,}2$: más que la cantidad.","120٪ = $1{,}2$: أكثر من الكمية."),explanation:t("$45\\cdot 1{,}2=54$")},{id:15,stage:"percent",prompt:a("$x$-ren % 30 255 da. Zenbat da $x$?","El 30 % de $x$ es 255. ¿Cuánto vale $x$?","30٪ من $x$ تساوي 255. كم قيمة $x$؟"),expected:r(850),hint:a("$x\\cdot 0{,}3=255$.","$x\\cdot 0{,}3=255$.","$x\\cdot 0{,}3=255$."),explanation:t("$x=255\\mathbin{:}0{,}3=850$")},{id:16,stage:"percent",prompt:a("Enpresa batek 24 eskaera jaso ditu eta 3 baztertu ditu. Zer ehuneko baztertu du?","Una empresa ha recibido 24 solicitudes y ha rechazado 3. ¿Qué porcentaje ha rechazado?","تلقّت شركة 24 طلبًا ورفضت 3. ما النسبة المرفوضة؟"),expected:c("12,5"),hint:a("Zatia : osoa · 100.","Parte : total · 100.","الجزء : الكل · 100."),explanation:t("$3\\mathbin{:}24\\cdot 100=12{,}5$")},{id:17,stage:"changes",prompt:a("Salmentak % 12 igo dira, eta hilabete honetan 2800 bote saldu dira. Zenbat saldu ziren aurreko hilabetean?","Las ventas han subido un 12 % y este mes se han vendido 2800 botes. ¿Cuántos se vendieron el mes pasado?","ارتفعت المبيعات 12٪ وبيع هذا الشهر 2800 علبة. كم علبة بيعت الشهر الماضي؟"),expected:r(2500),hint:a("Hasierakoa = amaierakoa : $1{,}12$.","Inicial = final : $1{,}12$.","الأصلية = النهائية : $1{,}12$."),explanation:t("$2800\\mathbin{:}1{,}12=2500$")},{id:18,stage:"changes",prompt:a("% 15 merkatutako gona batek $36{,}55$ € balio du. Zenbat balio zuen?","Una falda rebajada un 15 % cuesta $36{,}55$ €. ¿Cuánto costaba?","تنورة مخفّضة 15٪ ثمنها $36{,}55$ €. كم كان ثمنها؟"),expected:r(43),hint:a("% 85 ordaintzen da: zatitu $0{,}85$-ez.","Se paga el 85 %: divide entre $0{,}85$.","يُدفع 85٪: اقسم على $0{,}85$."),explanation:t("$36{,}55\\mathbin{:}0{,}85=43$")},{id:19,stage:"changes",prompt:a("200 €-ko jaka bat % 20 garestitu eta gero % 25 merkatu da. Zenbat balio du orain?","Una chaqueta de 200 € sube un 20 % y luego baja un 25 %. ¿Cuánto cuesta ahora?","سترة ثمنها 200 € ارتفعت 20٪ ثم انخفضت 25٪. كم ثمنها الآن؟"),expected:r(180),hint:a("Biderkatu indizeak: $1{,}2$ eta $0{,}75$.","Multiplica los índices: $1{,}2$ y $0{,}75$.","اضرب المؤشرين: $1{,}2$ و$0{,}75$."),explanation:t("$200\\cdot 1{,}2\\cdot 0{,}75=180$")},{id:20,stage:"changes",prompt:a("Zer interes sortzen dute 3500 €-k % 4an 3 urtez?","¿Qué interés producen 3500 € al 4 % durante 3 años?","ما الفائدة التي تُنتجها 3500 € بنسبة 4٪ مدة 3 سنوات؟"),expected:r(420),hint:a("$I=\\frac{C\\cdot r\\cdot t}{100}$.","$I=\\frac{C\\cdot r\\cdot t}{100}$.","$I=\\frac{C\\cdot r\\cdot t}{100}$."),explanation:t("$\\frac{3500\\cdot 4\\cdot 3}{100}=420$")}],da=[{id:101,stage:"proportions",points:10,context:"starter",prompt:a("Auto batek 6 l kontsumitzen ditu 100 km-ko. Zenbat litro 350 km-tan?","Un coche consume 6 l cada 100 km. ¿Cuántos litros gasta en 350 km?","تستهلك سيارة 6 ل لكل 100 كم. كم لترًا تستهلك في 350 كم؟"),expected:r(21),hint:a("Kilometro batean: $6\\mathbin{:}100$.","En un kilómetro: $6\\mathbin{:}100$.","في كيلومتر واحد: $6\\mathbin{:}100$."),explanation:t("$6\\mathbin{:}100\\cdot 350=21$")},{id:102,stage:"proportions",points:20,context:"advanced",prompt:a("Tren batek 3 ordu behar ditu 80 km/h-ra. Zenbat ordu 96 km/h-ra?","Un tren tarda 3 horas a 80 km/h. ¿Cuántas horas tarda a 96 km/h?","يستغرق قطار 3 ساعات بسرعة 80 كم/س. كم ساعة يستغرق بسرعة 96 كم/س؟"),expected:c("2,5"),hint:a("Ibilbidea: $80\\cdot 3$.","El trayecto: $80\\cdot 3$.","المسار: $80\\cdot 3$."),explanation:t("$80\\cdot 3=240\\ \\to\\ 240\\mathbin{:}96=2{,}5$")},{id:103,stage:"compound",points:20,context:"advanced",prompt:a("3 aspertsorek, $1{,}5$ l/s bakoitzak, biltegi bat 8 orduan husten dute. Zenbat ordu 4 aspertsorek, $0{,}9$ l/s bakoitzak?","3 aspersores de $1{,}5$ l/s cada uno vacían un depósito en 8 horas. ¿Cuántas horas tardan 4 aspersores de $0{,}9$ l/s?","3 رشّاشات تدفق كل منها $1{,}5$ ل/ث تفرغ خزانًا في 8 ساعات. كم ساعة تحتاج 4 رشّاشات تدفق كل منها $0{,}9$ ل/ث؟"),expected:r(10),hint:a("Biak alderantzizkoak: $\\frac{3}{4}$ eta $\\frac{1{,}5}{0{,}9}$.","Las dos inversas: $\\frac{3}{4}$ y $\\frac{1{,}5}{0{,}9}$.","كلاهما عكسي: $\\frac{3}{4}$ و$\\frac{1{,}5}{0{,}9}$."),explanation:t("$8\\cdot\\frac{3}{4}\\cdot\\frac{1{,}5}{0{,}9}=10$")},{id:104,stage:"compound",points:30,context:"advanced",prompt:a("15 langilek, egunean 8 ordu, 600 m-ko horma egiten dute 20 egunetan. Zenbat egun beharko dituzte 10 langilek, egunean 6 ordu, 300 m egiteko?","15 obreros, 8 horas al día, levantan un muro de 600 m en 20 días. ¿Cuántos días tardarán 10 obreros, 6 horas al día, en levantar 300 m?","15 عاملًا يعملون 8 ساعات يوميًا يبنون جدارًا طوله 600 م في 20 يومًا. كم يومًا يحتاج 10 عمال يعملون 6 ساعات يوميًا لبناء 300 م؟"),expected:r(20),hint:a("Metroak zuzena; langileak eta orduak alderantzizkoak.","Los metros, directa; los obreros y las horas, inversas.","الأمتار طردي؛ والعمال والساعات عكسي."),explanation:t("$20\\cdot\\frac{300}{600}\\cdot\\frac{15}{10}\\cdot\\frac{8}{6}=20$")},{id:105,stage:"compound",points:10,context:"starter",prompt:a("2 txorrotak 3 biltegi betetzen dituzte 6 orduan. Zenbat biltegi beteko dituzte 4 txorrotak 9 orduan?","2 grifos llenan 3 depósitos en 6 horas. ¿Cuántos depósitos llenarán 4 grifos en 9 horas?","صنبوران يملآن 3 خزانات في 6 ساعات. كم خزانًا تملأ 4 صنابير في 9 ساعات؟"),expected:r(9),hint:a("Biak zuzenak.","Las dos directas.","كلاهما طردي."),explanation:t("$3\\cdot\\frac{4}{2}\\cdot\\frac{9}{6}=9$")},{id:106,stage:"shares",points:10,context:"starter",prompt:a("Banatu 240 zuzenki proportzionalki 3 eta 5ekiko. Zenbat dagokio 5i?","Reparte 240 de forma directamente proporcional a 3 y 5. ¿Cuánto le toca al 5?","وزّع 240 طرديًا على 3 و5. كم نصيب 5؟"),expected:r(150),hint:a("8 zati.","8 partes.","8 أجزاء."),explanation:t("$240\\mathbin{:}8=30\\ \\to\\ 5\\cdot 30=150$")},{id:107,stage:"shares",points:20,context:"advanced",prompt:a("Banatu 3500 alderantziz proportzionalki 1, 2 eta 4rekiko. Zenbat dagokio 4ri?","Reparte 3500 de forma inversamente proporcional a 1, 2 y 4. ¿Cuánto le toca al 4?","وزّع 3500 عكسيًا على 1 و2 و4. كم نصيب 4؟"),expected:r(500),hint:a("Alderantzizkoak: $\\frac{4}{4},\\frac{2}{4},\\frac{1}{4}$.","Inversos: $\\frac{4}{4},\\frac{2}{4},\\frac{1}{4}$.","المقلوبات: $\\frac{4}{4},\\frac{2}{4},\\frac{1}{4}$."),explanation:t("$3500\\mathbin{:}(4+2+1)=500\\ \\to\\ 1\\cdot 500=500$")},{id:108,stage:"shares",points:30,context:"advanced",prompt:a("120 € banatzen dira 2, 3 eta 6 urteko hiru anaien artean, adinarekiko alderantziz proportzionalki. Zenbat jasotzen du 6 urtekoak?","Se reparten 120 € entre tres hermanos de 2, 3 y 6 años de forma inversamente proporcional a la edad. ¿Cuánto recibe el de 6 años?","تُوزَّع 120 € على ثلاثة إخوة أعمارهم 2 و3 و6 سنوات عكسيًا مع العمر. كم يأخذ ابن الست سنوات؟"),expected:r(20),hint:a("Alderantzizkoak: $\\frac{3}{6},\\frac{2}{6},\\frac{1}{6}$.","Inversos: $\\frac{3}{6},\\frac{2}{6},\\frac{1}{6}$.","المقلوبات: $\\frac{3}{6},\\frac{2}{6},\\frac{1}{6}$."),explanation:t("$120\\mathbin{:}(3+2+1)=20\\ \\to\\ 1\\cdot 20=20$")},{id:109,stage:"percent",points:10,context:"starter",prompt:a("$x$-ren % 25 $42{,}5$ da. Zenbat da $x$?","El 25 % de $x$ es $42{,}5$. ¿Cuánto vale $x$?","25٪ من $x$ تساوي $42{,}5$. كم قيمة $x$؟"),expected:r(170),hint:a("Zatitu $0{,}25$-ez.","Divide entre $0{,}25$.","اقسم على $0{,}25$."),explanation:t("$42{,}5\\mathbin{:}0{,}25=170$")},{id:110,stage:"percent",points:20,context:"advanced",prompt:a("Prezio bat 80 €-tik 92 €-ra igo da. Zer ehuneko igo da?","Un precio ha pasado de 80 € a 92 €. ¿Qué porcentaje ha subido?","ارتفع سعر من 80 € إلى 92 €. بأي نسبة ارتفع؟"),expected:r(15),hint:a("Amaierakoa : hasierakoa · 100.","Final : inicial · 100.","النهائية : الأصلية · 100."),explanation:t("$92\\mathbin{:}80\\cdot 100=115\\ \\to\\ 115-100=15$")},{id:111,stage:"changes",points:20,context:"advanced",prompt:a("Hiri batean Interneteko erabiltzaileak 21 000 dira, iaz baino % 20 gehiago. Zenbat ziren iaz?","En una ciudad hay 21 000 usuarios de Internet, un 20 % más que el año pasado. ¿Cuántos había el año pasado?","في مدينة 21000 مستخدم للإنترنت، بزيادة 20٪ عن العام الماضي. كم كانوا العام الماضي؟"),expected:r(17500),hint:a("Zatitu $1{,}2$-z.","Divide entre $1{,}2$.","اقسم على $1{,}2$."),explanation:t("$21\\,000\\mathbin{:}1{,}2=17\\,500$")},{id:112,stage:"changes",points:30,context:"advanced",prompt:a("Prezio bat % 20 igo eta gero % 20 jaisten da. Hasierako prezioaren zer ehuneko ordaintzen da?","Un precio sube un 20 % y luego baja un 20 %. ¿Qué porcentaje del precio inicial se paga?","يرتفع سعر 20٪ ثم ينخفض 20٪. ما النسبة المدفوعة من السعر الأصلي؟"),expected:r(96),hint:a("Biderkatu indizeak.","Multiplica los índices.","اضرب المؤشرين."),explanation:t("$1{,}2\\cdot 0{,}8=0{,}96\\ \\to\\ 96$")},{id:113,stage:"changes",points:20,context:"advanced",prompt:a("Zer kapitalek sortzen ditu 600 € interes % 5ean 4 urtetan?","¿Qué capital produce 600 € de interés al 5 % en 4 años?","أي رأس مال يُنتج فائدة 600 € بنسبة 5٪ في 4 سنوات؟"),expected:r(3e3),hint:a("$600=\\frac{C\\cdot 5\\cdot 4}{100}$.","$600=\\frac{C\\cdot 5\\cdot 4}{100}$.","$600=\\frac{C\\cdot 5\\cdot 4}{100}$."),explanation:t("$\\frac{600\\cdot 100}{5\\cdot 4}=3000$")},{id:114,stage:"changes",points:30,context:"advanced",prompt:a("Prezio bat % 30 jaitsi eta gero % 30 igotzen da. Hasierakoaren zer ehuneko da amaierakoa?","Un precio baja un 30 % y luego sube un 30 %. ¿Qué porcentaje del inicial es el final?","ينخفض سعر 30٪ ثم يرتفع 30٪. ما نسبة النهائي من الأصلي؟"),expected:r(91),hint:a("$0{,}7$ eta $1{,}3$.","$0{,}7$ y $1{,}3$.","$0{,}7$ و$1{,}3$."),explanation:t("$0{,}7\\cdot 1{,}3=0{,}91\\ \\to\\ 91$")}],sa=[{id:"proportions",title:a("Proportzioak (errepasoa)","Proporciones (repaso)","التناسبات (مراجعة)"),items:[{id:1,difficulty:"easy",question:a("Kalkulatu 5en eta 15en arteko arrazoia, zatiki sinplifikatu gisa.","Calcula la razón entre 5 y 15 como fracción simplificada.","احسب النسبة بين 5 و15 كسرًا مبسّطًا."),solution:t("$\\frac{5}{15}=\\frac{1}{3}$"),answer:{expected:$(1,3)}},{id:2,difficulty:"easy",question:a("$\\frac{3}{6}$ eta $\\frac{4}{8}$ proportzio bat osatzen dute?","¿Forman $\\frac{3}{6}$ y $\\frac{4}{8}$ una proporción?","هل يكوّن $\\frac{3}{6}$ و$\\frac{4}{8}$ تناسبًا؟"),solution:a("Bai: $3\\cdot 8=24$ eta $6\\cdot 4=24$.","Sí: $3\\cdot 8=24$ y $6\\cdot 4=24$.","نعم: $3\\cdot 8=24$ و$6\\cdot 4=24$.")},{id:3,difficulty:"easy",question:a("Aurkitu $x$: $\\frac{4}{10}=\\frac{6}{x}$.","Halla $x$: $\\frac{4}{10}=\\frac{6}{x}$.","أوجد $x$: $\\frac{4}{10}=\\frac{6}{x}$."),solution:t("$4\\cdot x=60\\ \\to\\ x=60\\mathbin{:}4=15$"),answer:{expected:r(15)}},{id:4,difficulty:"medium",question:a("Zuzena, alderantzizkoa ala bat ere ez? a) Langile kopurua eta lan bat egiteko denbora; b) kiloak eta prezioa; c) adina eta altuera.","¿Directa, inversa o ninguna? a) Número de obreros y tiempo para hacer una obra; b) kilos y precio; c) edad y altura.","طردي أم عكسي أم لا شيء؟ أ) عدد العمال وزمن إنجاز عمل؛ ب) الكيلوغرامات والسعر؛ ج) العمر والطول."),solution:a("a) Alderantzizkoa; b) zuzena; c) bat ere ez.","a) Inversa; b) directa; c) ninguna.","أ) عكسي؛ ب) طردي؛ ج) لا شيء.")},{id:5,difficulty:"medium",question:a("3 kg laranjak $2{,}40$ € balio dute. Zenbat balio dute 8 kg-k?","3 kg de naranjas cuestan $2{,}40$ €. ¿Cuánto cuestan 8 kg?","ثمن 3 كغ من البرتقال $2{,}40$ €. كم ثمن 8 كغ؟"),solution:t("$2{,}40\\mathbin{:}3=0{,}8\\ \\to\\ 0{,}8\\cdot 8=6{,}4$"),answer:{expected:c("6,4")}},{id:6,difficulty:"medium",question:a("4 langilek 15 egunetan bukatzen dute lan bat. Zenbat egunetan 6 langilek?","4 obreros terminan una obra en 15 días. ¿En cuántos días la terminan 6 obreros?","4 عمال ينهون عملًا في 15 يومًا. في كم يومًا ينهيه 6 عمال؟"),solution:t("$4\\cdot 15=60\\ \\to\\ 60\\mathbin{:}6=10$"),answer:{expected:r(10)}},{id:7,difficulty:"medium",question:a("Txirrindulari batek $6{,}3$ km egin ditu 18 minututan. Zein da haren abiadura km/h-tan?","Un ciclista ha recorrido $6{,}3$ km en 18 minutos. ¿Cuál es su velocidad en km/h?","قطع دراج $6{,}3$ كم في 18 دقيقة. ما سرعته بالكيلومتر في الساعة؟"),solution:t("$6{,}3\\mathbin{:}18\\cdot 60=21$"),answer:{expected:r(21)}},{id:8,difficulty:"hard",question:a("Merkantzia-tren batek 7 ordu behar ditu 72 km/h-ra. Zer abiadurarekin egingo luke 6 ordutan?","Un tren de mercancías tarda 7 horas a 72 km/h. ¿A qué velocidad tardaría 6 horas?","يستغرق قطار بضائع 7 ساعات بسرعة 72 كم/س. بأي سرعة يستغرق 6 ساعات؟"),solution:t("$72\\cdot 7=504\\ \\to\\ 504\\mathbin{:}6=84$"),answer:{expected:r(84)}},{id:9,difficulty:"hard",question:a("12 l/min-ko txorrota batek 25 minututan betetzen du biltegi bat. Zer emari behar da 20 minututan betetzeko?","Un grifo de 12 l/min llena un depósito en 25 minutos. ¿Qué caudal hace falta para llenarlo en 20 minutos?","صنبور تدفقه 12 ل/د يملأ خزانًا في 25 دقيقة. ما التدفق اللازم لملئه في 20 دقيقة؟"),solution:t("$12\\cdot 25=300\\ \\to\\ 300\\mathbin{:}20=15$"),answer:{expected:r(15)}},{id:10,difficulty:"hard",question:a("Bi zenbakiren arrazoia $\\frac{3}{4}$ da eta haien batura 84. Zein da handiena?","La razón de dos números es $\\frac{3}{4}$ y su suma es 84. ¿Cuál es el mayor?","نسبة عددين $\\frac{3}{4}$ ومجموعهما 84. ما الأكبر؟"),solution:t("$84\\mathbin{:}(3+4)=12\\ \\to\\ 4\\cdot 12=48$"),answer:{expected:r(48)}}]},{id:"compound",title:a("Proportzionaltasun konposatua","Proporcionalidad compuesta","التناسب المركّب"),items:[{id:11,difficulty:"easy",question:a("Horma bera egiteko, langile gehiago badaude, egun gehiago ala gutxiago behar dira? Eta horma luzeagoa bada?","Para hacer el mismo muro, si hay más obreros, ¿hacen falta más o menos días? ¿Y si el muro es más largo?","لبناء الجدار نفسه، إذا زاد العمال فهل نحتاج أيامًا أكثر أم أقل؟ وإذا كان الجدار أطول؟"),solution:a("Langile gehiago → egun gutxiago (alderantzizkoa). Horma luzeagoa → egun gehiago (zuzena).","Más obreros → menos días (inversa). Muro más largo → más días (directa).","عمال أكثر ← أيام أقل (عكسي). جدار أطول ← أيام أكثر (طردي).")},{id:12,difficulty:"easy",question:a("2 makinak 3 orduan 600 pieza egiten dituzte. Zenbat pieza 4 makinak 3 orduan?","2 máquinas hacen 600 piezas en 3 horas. ¿Cuántas piezas hacen 4 máquinas en 3 horas?","آلتان تصنعان 600 قطعة في 3 ساعات. كم قطعة تصنع 4 آلات في 3 ساعات؟"),solution:t("$600\\cdot\\frac{4}{2}\\cdot\\frac{3}{3}=1200$"),answer:{expected:r(1200)}},{id:13,difficulty:"medium",question:a("6 makinak 4 orduan 1200 pieza egiten dituzte. Zenbat pieza 9 makinak 5 orduan?","6 máquinas hacen 1200 piezas en 4 horas. ¿Cuántas piezas hacen 9 máquinas en 5 horas?","6 آلات تصنع 1200 قطعة في 4 ساعات. كم قطعة تصنع 9 آلات في 5 ساعات؟"),solution:t("$1200\\cdot\\frac{9}{6}\\cdot\\frac{5}{4}=2250$"),answer:{expected:r(2250)}},{id:14,difficulty:"medium",question:a("9 langilek, egunean 6 ordu, 20 egunetan bukatzen dute lan bat. Zenbat egun 12 langilek, egunean 5 ordu?","9 obreros, 6 horas al día, terminan una obra en 20 días. ¿Cuántos días tardan 12 obreros, 5 horas al día?","9 عمال يعملون 6 ساعات يوميًا ينهون عملًا في 20 يومًا. كم يومًا يحتاج 12 عاملًا يعملون 5 ساعات يوميًا؟"),solution:t("$20\\cdot\\frac{9}{12}\\cdot\\frac{6}{5}=18$"),answer:{expected:r(18)}},{id:15,difficulty:"medium",question:a("Nekazari batek 294 kg pentsu behar izan ditu 15 behi 7 egunez elikatzeko. 840 kg-rekin, zenbat egun elika ditzake 10 behi?","Un granjero ha necesitado 294 kg de pienso para 15 vacas durante 7 días. Con 840 kg, ¿cuántos días puede alimentar a 10 vacas?","احتاج مزارع 294 كغ من العلف لـ15 بقرة مدة 7 أيام. بـ840 كغ، كم يومًا يطعم 10 أبقار؟"),solution:t("$7\\cdot\\frac{840}{294}\\cdot\\frac{15}{10}=30$"),answer:{expected:r(30)}},{id:16,difficulty:"medium",question:a("Hondeamakina batek, egunean 10 ordu, 1000 m-ko zanga egiten du 8 egunetan. Zenbat egun 600 m-ko zanga, egunean 12 ordu?","Una excavadora, 10 horas al día, abre 1000 m de zanja en 8 días. ¿Cuántos días tarda en abrir 600 m trabajando 12 horas al día?","حفّارة تعمل 10 ساعات يوميًا تحفر 1000 م في 8 أيام. كم يومًا تحتاج لحفر 600 م إذا عملت 12 ساعة يوميًا؟"),solution:t("$8\\cdot\\frac{600}{1000}\\cdot\\frac{10}{12}=4$"),answer:{expected:r(4)}},{id:17,difficulty:"hard",question:a("4 lagunek 10 egunetan 600 l ur kontsumitzen dituzte. Zenbat litro 6 lagunek 15 egunetan?","4 personas consumen 600 l de agua en 10 días. ¿Cuántos litros consumen 6 personas en 15 días?","4 أشخاص يستهلكون 600 ل من الماء في 10 أيام. كم لترًا يستهلك 6 أشخاص في 15 يومًا؟"),solution:t("$600\\cdot\\frac{6}{4}\\cdot\\frac{15}{10}=1350$"),answer:{expected:r(1350)}},{id:18,difficulty:"hard",question:a("Igeltsero talde batek, egunean 10 ordu, 600 m² horma egin ditu 18 egunetan. Zenbat m² egingo ditu 15 egunetan, egunean 8 ordu?","Una cuadrilla, 10 horas al día, ha construido 600 m² de pared en 18 días. ¿Cuántos m² construirá en 15 días, 8 horas al día?","مجموعة بنّائين تعمل 10 ساعات يوميًا بنت 600 م² في 18 يومًا. كم م² تبني في 15 يومًا بـ8 ساعات يوميًا؟"),solution:t("$600\\cdot\\frac{8}{10}\\cdot\\frac{15}{18}=400$"),answer:{expected:r(400)}},{id:19,difficulty:"hard",question:a("Biltegi bat 2 l/s-ko 5 txorrotarekin 6 orduan betetzen da. Zenbat ordu 4 l/s-ko 3 txorrotarekin?","Un depósito se llena con 5 grifos de 2 l/s en 6 horas. ¿Cuántas horas tarda con 3 grifos de 4 l/s?","يُملأ خزان بـ5 صنابير تدفق كل منها 2 ل/ث في 6 ساعات. كم ساعة يحتاج بـ3 صنابير تدفق كل منها 4 ل/ث؟"),solution:t("$5\\cdot 2\\cdot 6=60\\ \\to\\ 60\\mathbin{:}(3\\cdot 4)=5$"),answer:{expected:r(5)}},{id:20,difficulty:"hard",question:a("Zergatik biderkatzen dira zatikiak proportzionaltasun konposatuan? Azaldu adibide batekin.","¿Por qué se multiplican las fracciones en la proporcionalidad compuesta? Explícalo con un ejemplo.","لماذا نضرب الكسور في التناسب المركّب؟ اشرح بمثال."),solution:a("Magnitude bakoitzak bere aldetik aldatzen du emaitza: lehenik bat aldatzen da (biderkatu zatiki batez), gero bestea (biderkatu beste batez). Bi urratsak jarraian = bi zatikien biderkadura.","Cada magnitud cambia el resultado por separado: primero se cambia una (multiplicar por una fracción), luego la otra (multiplicar por otra). Los dos pasos seguidos = el producto de las dos fracciones.","كل مقدار يغيّر النتيجة على حدة: نغيّر الأول (نضرب في كسر) ثم الثاني (نضرب في كسر آخر). والخطوتان متتاليتين = حاصل ضرب الكسرين.")}]},{id:"shares",title:a("Banaketa proportzionalak","Repartos proporcionales","التوزيعات التناسبية"),items:[{id:21,difficulty:"easy",question:a("Banatu 180 zuzenki proportzionalki 2, 5 eta 8rekiko.","Reparte 180 de forma directamente proporcional a 2, 5 y 8.","وزّع 180 طرديًا على 2 و5 و8."),solution:t("$180\\mathbin{:}15=12\\ \\to\\ 24,\\ 60,\\ 96$")},{id:22,difficulty:"easy",question:a("Banatu 120 zuzenki proportzionalki 1 eta 3rekiko. Zein da zati handiena?","Reparte 120 de forma directamente proporcional a 1 y 3. ¿Cuál es la parte mayor?","وزّع 120 طرديًا على 1 و3. ما الجزء الأكبر؟"),solution:t("$120\\mathbin{:}4=30\\ \\to\\ 3\\cdot 30=90$"),answer:{expected:r(90)}},{id:23,difficulty:"easy",question:a("Alderantzizko banaketa batean, zenbaki handienari zati handiena ala txikiena dagokio?","En un reparto inverso, ¿al número mayor le toca la parte mayor o la menor?","في التوزيع العكسي، هل يأخذ العدد الأكبر الجزء الأكبر أم الأصغر؟"),solution:a("Txikiena.","La menor.","الأصغر.")},{id:24,difficulty:"medium",question:a("Hiru familiak apartamentu bat 20 egunez alokatu dute 1200 €-an: 7, 6 eta 7 egun. Zenbat ordaintzen du bakoitzak?","Tres familias alquilan un apartamento 20 días por 1200 €: 7, 6 y 7 días. ¿Cuánto paga cada una?","استأجرت ثلاث عائلات شقة 20 يومًا بـ1200 €: 7 و6 و7 أيام. كم تدفع كل عائلة؟"),solution:t("$1200\\mathbin{:}20=60\\ \\to\\ 420,\\ 360,\\ 420$")},{id:25,difficulty:"medium",question:a("Banatu 130 zuzenki proportzionalki $\\frac{1}{2}$, $\\frac{1}{3}$ eta $\\frac{1}{4}$-rekiko.","Reparte 130 de forma directamente proporcional a $\\frac{1}{2}$, $\\frac{1}{3}$ y $\\frac{1}{4}$.","وزّع 130 طرديًا على $\\frac{1}{2}$ و$\\frac{1}{3}$ و$\\frac{1}{4}$."),solution:t("$\\frac{6}{12},\\frac{4}{12},\\frac{3}{12}\\ \\to\\ 130\\mathbin{:}13=10\\ \\to\\ 60,\\ 40,\\ 30$")},{id:26,difficulty:"medium",question:a("Banatu 620 alderantziz proportzionalki 2, 3 eta 5ekiko.","Reparte 620 de forma inversamente proporcional a 2, 3 y 5.","وزّع 620 عكسيًا على 2 و3 و5."),solution:t("$\\frac{15}{30},\\frac{10}{30},\\frac{6}{30}\\ \\to\\ 620\\mathbin{:}31=20\\ \\to\\ 300,\\ 200,\\ 120$")},{id:27,difficulty:"medium",question:a("Bi bazkidek 4000 € eta 6000 € jarri dituzte, eta 2500 € irabazi. Zenbat dagokio bigarrenari?","Dos socios ponen 4000 € y 6000 € y ganan 2500 €. ¿Cuánto le toca al segundo?","وضع شريكان 4000 € و6000 € وربحا 2500 €. كم نصيب الثاني؟"),solution:t("$2500\\mathbin{:}(4+6)=250\\ \\to\\ 6\\cdot 250=1500$"),answer:{expected:r(1500)}},{id:28,difficulty:"hard",question:a("22 000 €-ko saria hiru lehenengoen artean banatzen da, postuarekiko alderantziz. Zenbat irabazten du lehenengoak?","Un premio de 22 000 € se reparte entre los tres primeros de forma inversa al puesto. ¿Cuánto gana el primero?","تُوزَّع جائزة 22000 € على الثلاثة الأوائل عكسيًا مع الترتيب. كم يربح الأول؟"),solution:t("$\\frac{6}{6},\\frac{3}{6},\\frac{2}{6}\\ \\to\\ 22\\,000\\mathbin{:}11=2000\\ \\to\\ 6\\cdot 2000=12\\,000$"),answer:{expected:r(12e3)}},{id:29,difficulty:"hard",question:a("Banatu 2000 alderantziz proportzionalki $\\frac{1}{2}$, $\\frac{1}{3}$ eta $\\frac{1}{5}$-ekiko. Zein da zati handiena?","Reparte 2000 de forma inversamente proporcional a $\\frac{1}{2}$, $\\frac{1}{3}$ y $\\frac{1}{5}$. ¿Cuál es la parte mayor?","وزّع 2000 عكسيًا على $\\frac{1}{2}$ و$\\frac{1}{3}$ و$\\frac{1}{5}$. ما الجزء الأكبر؟"),solution:a("Alderantzizkoak 2, 3 eta 5 dira: $2000\\mathbin{:}10=200\\ \\to\\ 400,\\ 600,\\ 1000$.","Los inversos son 2, 3 y 5: $2000\\mathbin{:}10=200\\ \\to\\ 400,\\ 600,\\ 1000$.","المقلوبات 2 و3 و5: $2000\\mathbin{:}10=200\\ \\to\\ 400,\\ 600,\\ 1000$."),answer:{expected:r(1e3)}},{id:30,difficulty:"hard",question:a("1500, 2500 eta 4000 biztanleko hiru herrik 24 000 €-ko diru-laguntza banatzen dute biztanleen arabera. Zenbat dagokio 2500ekoari?","Tres pueblos de 1500, 2500 y 4000 habitantes reparten una subvención de 24 000 € según sus habitantes. ¿Cuánto le toca al de 2500?","ثلاث قرى سكانها 1500 و2500 و4000 تتقاسم منحة 24000 € حسب السكان. كم نصيب قرية الـ2500؟"),solution:t("$24\\,000\\mathbin{:}8000=3\\ \\to\\ 2500\\cdot 3=7500$"),answer:{expected:r(7500)}}]},{id:"percent",title:a("Ehunekoak","Porcentajes","النسب المئوية"),items:[{id:31,difficulty:"easy",question:a("Kalkulatu buruz: 200en % 20.","Calcula mentalmente: el 20 % de 200.","احسب ذهنيًا: 20٪ من 200."),solution:t("$200\\cdot 0{,}2=40$"),answer:{expected:r(40)}},{id:32,difficulty:"easy",question:a("Idatzi hamartar gisa: % 35, % 8, % 120.","Escribe como decimal: 35 %, 8 %, 120 %.","اكتب عددًا عشريًا: 35٪، 8٪، 120٪."),solution:t("$0{,}35\\qquad 0{,}08\\qquad 1{,}2$")},{id:33,difficulty:"easy",question:a("Enpresa bateko zuzendarien % 62 gizonak dira. Zer ehuneko dira emakumeak?","El 62 % de los directivos de una empresa son hombres. ¿Qué porcentaje son mujeres?","62٪ من مديري شركة رجال. ما نسبة النساء؟"),solution:t("$100-62=38$"),answer:{expected:r(38)}},{id:34,difficulty:"medium",question:a("Kalkulatu 750en % 12.","Calcula el 12 % de 750.","احسب 12٪ من 750."),solution:t("$750\\cdot 0{,}12=90$"),answer:{expected:r(90)}},{id:35,difficulty:"medium",question:a("Kalkulatu 20ren % 2,5.","Calcula el 2,5 % de 20.","احسب 2.5٪ من 20."),solution:t("$20\\cdot 0{,}025=0{,}5$"),answer:{expected:c("0,5")}},{id:36,difficulty:"medium",question:a("$x$-ren % 13 $7{,}54$ da. Zenbat da $x$?","El 13 % de $x$ es $7{,}54$. ¿Cuánto vale $x$?","13٪ من $x$ تساوي $7{,}54$. كم قيمة $x$؟"),solution:t("$x=7{,}54\\mathbin{:}0{,}13=58$"),answer:{expected:r(58)}},{id:37,difficulty:"medium",question:a("175 ardiko artalde batean 14 beltzak dira. Zer ehuneko?","En un rebaño de 175 ovejas, 14 son negras. ¿Qué porcentaje?","في قطيع من 175 نعجة، 14 سوداء. ما النسبة؟"),solution:t("$14\\mathbin{:}175\\cdot 100=8$"),answer:{expected:r(8)}},{id:38,difficulty:"hard",question:a("Hegazkin batek 425 bidaiari daramatza: % 52 europarrak, % 28 amerikarrak, % 12 afrikarrak eta gainerakoak asiarrak. Zenbat asiar?","Un avión lleva 425 viajeros: el 52 % europeos, el 28 % americanos, el 12 % africanos y el resto asiáticos. ¿Cuántos asiáticos?","تنقل طائرة 425 مسافرًا: 52٪ أوروبيون و28٪ أمريكيون و12٪ أفارقة والباقي آسيويون. كم آسيويًا؟"),solution:t("$100-52-28-12=8\\ \\to\\ 425\\cdot 0{,}08=34$"),answer:{expected:r(34)}},{id:39,difficulty:"hard",question:a("Albertok 111 € ordaindu ditu 148 € balio zuen beroki batengatik. Zer ehuneko beherapen?","Alberto ha pagado 111 € por un abrigo de 148 €. ¿Qué porcentaje de descuento?","دفع ألبرتو 111 € ثمن معطف سعره 148 €. ما نسبة الخصم؟"),solution:t("$111\\mathbin{:}148\\cdot 100=75\\ \\to\\ 100-75=25$"),answer:{expected:r(25)}},{id:40,difficulty:"hard",question:a("15 milioi biztanleko herrialde batean % 8 etorkinak dira. Zenbat milioi?","En un país de 15 millones de habitantes, el 8 % son inmigrantes. ¿Cuántos millones?","في بلد عدد سكانه 15 مليونًا، 8٪ مهاجرون. كم مليونًا؟"),solution:t("$15\\cdot 0{,}08=1{,}2$"),answer:{expected:c("1,2")}}]},{id:"changes",title:a("Aldakuntzak eta interesa","Variaciones e interés","التغيّرات والفائدة"),items:[{id:41,difficulty:"easy",question:a("Idatzi aldakuntza-indizea: a) % 18 igo; b) % 7 jaitsi; c) % 100 igo.","Escribe el índice de variación: a) subir un 18 %; b) bajar un 7 %; c) subir un 100 %.","اكتب مؤشر التغيّر: أ) زيادة 18٪؛ ب) تخفيض 7٪؛ ج) زيادة 100٪."),solution:t("$1{,}18\\qquad 0{,}93\\qquad 2$")},{id:42,difficulty:"easy",question:a("Aurreko hilabetean 2500 bote saldu ziren eta salmentak % 12 igo dira. Zenbat bote orain?","El mes pasado se vendieron 2500 botes y las ventas han subido un 12 %. ¿Cuántos botes ahora?","بيعت الشهر الماضي 2500 علبة وارتفعت المبيعات 12٪. كم علبة الآن؟"),solution:t("$2500\\cdot 1{,}12=2800$"),answer:{expected:r(2800)}},{id:43,difficulty:"easy",question:a("Zer interes sortzen dute 600 €-k % 5ean urte batean?","¿Qué interés producen 600 € al 5 % en un año?","ما الفائدة التي تُنتجها 600 € بنسبة 5٪ في سنة؟"),solution:t("$\\frac{600\\cdot 5\\cdot 1}{100}=30$"),answer:{expected:r(30)}},{id:44,difficulty:"medium",question:a("Soldata % 10 igo ondoren, Martak 1760 € irabazten ditu. Zenbat zen lehen?","Tras una subida del 10 %, Marta gana 1760 €. ¿Cuánto ganaba antes?","بعد زيادة 10٪ صارت مارتا تربح 1760 €. كم كانت تربح قبل ذلك؟"),solution:t("$1760\\mathbin{:}1{,}1=1600$"),answer:{expected:r(1600)}},{id:45,difficulty:"medium",question:a("Interneteko erabiltzaileak 21 000 dira, iaz baino % 20 gehiago. Zenbat ziren?","Hay 21 000 usuarios de Internet, un 20 % más que el año pasado. ¿Cuántos había?","عدد مستخدمي الإنترنت 21000، بزيادة 20٪ عن العام الماضي. كم كانوا؟"),solution:t("$21\\,000\\mathbin{:}1{,}2=17\\,500$"),answer:{expected:r(17500)}},{id:46,difficulty:"medium",question:a("Kalkulatu 8000 €-k % 5ean 3 urtez sortzen duten interesa.","Calcula el interés que producen 8000 € al 5 % durante 3 años.","احسب الفائدة التي تُنتجها 8000 € بنسبة 5٪ مدة 3 سنوات."),solution:t("$\\frac{8000\\cdot 5\\cdot 3}{100}=1200$"),answer:{expected:r(1200)}},{id:47,difficulty:"medium",question:a("100 €-ko produktu bat % 10 igo eta gero % 10 jaisten da. Zenbat balio du?","Un producto de 100 € sube un 10 % y luego baja un 10 %. ¿Cuánto cuesta?","منتج ثمنه 100 € يرتفع 10٪ ثم ينخفض 10٪. كم ثمنه؟"),solution:t("$100\\cdot 1{,}1\\cdot 0{,}9=99$"),answer:{expected:r(99)}},{id:48,difficulty:"hard",question:a("80 €-ko produktu bat % 15 igo eta gero % 20 jaisten da. Zenbat balio du?","Un producto de 80 € sube un 15 % y luego baja un 20 %. ¿Cuánto cuesta?","منتج ثمنه 80 € يرتفع 15٪ ثم ينخفض 20٪. كم ثمنه؟"),solution:t("$80\\cdot 1{,}15\\cdot 0{,}8=73{,}6$"),answer:{expected:c("73,6")}},{id:49,difficulty:"hard",question:a("Zenbat urtetan sortzen dituzte 2000 €-k % 4an 400 € interes?","¿En cuántos años producen 2000 € al 4 % un interés de 400 €?","في كم سنة تُنتج 2000 € بنسبة 4٪ فائدة 400 €؟"),solution:t("$t=\\frac{400\\cdot 100}{2000\\cdot 4}=5$"),answer:{expected:r(5)}},{id:50,difficulty:"hard",question:a("Zer interes-tasarekin sortzen dituzte 5000 €-k 750 € 3 urtetan?","¿A qué tipo de interés producen 5000 € un interés de 750 € en 3 años?","بأي سعر فائدة تُنتج 5000 € فائدة 750 € في 3 سنوات؟"),solution:t("$r=\\frac{750\\cdot 100}{5000\\cdot 3}=5$"),answer:{expected:r(5)}}]}];function p({game:o}){return o==="race"?i.jsxs("svg",{className:"fraction-v2-game-art",viewBox:"0 0 220 120","aria-hidden":"true",children:[i.jsx("rect",{x:"6",y:"36",width:"208",height:"52",rx:"10",fill:"var(--paper-deep)",stroke:"var(--ink)",strokeWidth:"2"}),i.jsx("line",{x1:"14",y1:"62",x2:"206",y2:"62",stroke:"var(--line)",strokeWidth:"2",strokeDasharray:"8 7"}),i.jsx(m,{color:"var(--coral)",label:"%",x:104,y:20,width:72}),i.jsx(m,{color:"var(--blue)",x:40,y:50,width:62}),i.jsx("text",{x:"110",y:"112",textAnchor:"middle",fontSize:"16",fontWeight:"700",fill:"var(--ink)",direction:"ltr",children:"600 · 8/10 · 15/18"})]}):i.jsx("svg",{className:"fraction-v2-game-art",viewBox:"0 0 220 120","aria-hidden":"true",children:["+12%","×112/100","−15%","×85/100"].map((d,s)=>i.jsxs("g",{transform:`translate(${14+s*50} ${s%2===0?24:40}) rotate(${s%2===0?-4:4})`,children:[i.jsx("rect",{width:"44",height:"60",rx:"8",fill:s%2===0?"var(--paper-deep)":"var(--blue-tint, #dde7f7)",stroke:"var(--ink)",strokeWidth:"2"}),i.jsx("text",{x:"22",y:"36",textAnchor:"middle",fontSize:d.length>5?8:11,fontWeight:"700",fill:"var(--ink)",direction:"ltr",children:d})]},d))})}const b="matella-proportzionaltasuna-dbh2-game-records",l=[{id:"race",title:{eu:"Proportzioen lasterketa",es:"Carrera de proporciones",ar:"سباق التناسب"},tagline:{eu:"Erantzun ondo eta azkar: zure autoa aurrera doa, akatsek irrist egiten dute.",es:"Responde bien y rápido: tu coche avanza, los errores le hacen derrapar.",ar:"أجب بدقة وسرعة: تتقدم سيارتك، والأخطاء تجعلها تنزلق."},skills:{eu:"Bost zirkuitu, etapa bakoitzeko bat",es:"Cinco circuitos, uno por etapa",ar:"خمس حلبات، واحدة لكل مرحلة"},levels:[{progressId:22101,stage:"proportions",title:{eu:"Proportzioak",es:"Proporciones",ar:"التناسبات"},description:{eu:"Laugarren proportzionala eta alderantzizkoa.",es:"Cuarto proporcional e inversa.",ar:"الرابع المتناسب والعكسي."}},{progressId:22102,stage:"compound",title:{eu:"Konposatua",es:"Compuesta",ar:"المركّب"},description:{eu:"Bi magnitude aldi berean.",es:"Dos magnitudes a la vez.",ar:"مقداران معًا."}},{progressId:22103,stage:"shares",title:{eu:"Banaketak",es:"Repartos",ar:"التوزيعات"},description:{eu:"Zuzenak eta alderantzizkoak.",es:"Directos e inversos.",ar:"طردية وعكسية."}},{progressId:22104,stage:"percent",title:{eu:"Ehunekoak",es:"Porcentajes",ar:"النسب المئوية"},description:{eu:"Zatia, osoa eta aldakuntza.",es:"La parte, el total y la variación.",ar:"الجزء والكل والتغيّر."}},{progressId:22105,stage:"changes",title:{eu:"Indizeak eta interesa",es:"Índices e interés",ar:"المؤشرات والفائدة"},description:{eu:"Hasierakoa, kateatuak eta interesa.",es:"La inicial, encadenados e interés.",ar:"الأصلية والمتتالية والفائدة."}}]},{id:"memory",title:{eu:"Memoria",es:"Memoria",ar:"الذاكرة"},tagline:{eu:"Aurkitu balio bera duten kartak.",es:"Encuentra las cartas que valen lo mismo.",ar:"جد البطاقات ذات القيمة نفسها."},skills:{eu:"Ehunekoak, indizeak eta kateatuak",es:"Porcentajes, índices y encadenados",ar:"النسب والمؤشرات والمتتالية"},levels:[{progressId:22201,stage:"percent",title:{eu:"Ehunekoa eta hamartarra",es:"Porcentaje y decimal",ar:"النسبة والعدد العشري"},description:{eu:"120 % ↔ 1,2",es:"120 % ↔ 1,2",ar:"120٪ ↔ 1.2"}},{progressId:22202,stage:"changes",title:{eu:"Aldakuntza-indizea",es:"Índice de variación",ar:"مؤشر التغيّر"},description:{eu:"−15 % ↔ · 0,85",es:"−15 % ↔ · 0,85",ar:"−15٪ ↔ · 0.85"}},{progressId:22203,stage:"changes",title:{eu:"Indize kateatuak",es:"Índices encadenados",ar:"المؤشرات المتتالية"},description:{eu:"1,1 · 0,9 ↔ 0,99",es:"1,1 · 0,9 ↔ 0,99",ar:"1.1 · 0.9 ↔ 0.99"}}]}],ca=f(l),ua={race:"lasterketa",memory:"memoria"};function la(o){const d=o.match(/\/(?:juegos|jokuak)\/([a-z-]+)$/)?.[1];return d?["carrera","lasterketa"].includes(d)?"race":["memoria","memory"].includes(d)?"memory":"hub":"hub"}const $a={game:l.find(o=>o.id==="race"),generate:B,checkPit:w,parTime:P,errorTip:o=>I[o??"calculation"],pitPlaceholder:()=>"30",pitUnreadable:{eu:"Idatzi zenbaki bat, adibidez 30 edo 10,8.",es:"Escribe un número, por ejemplo 30 o 10,8.",ar:"اكتب عددًا، مثل 30 أو 10.8."},pitWrongForm:{eu:"Idatzi zenbaki gisa.",es:"Escríbelo como número.",ar:"اكتبه عددًا."}};function pa(o){return i.jsx(x,{...o,rules:$a,art:i.jsx(p,{game:"race"})})}const ka=l.find(o=>o.id==="memory"),ma={race:pa,memory:o=>i.jsx(aa,{...o,config:{game:ka,art:i.jsx(p,{game:"memory"}),pairs:D,createBoard:A}})},ba=l.map(o=>({info:o,art:i.jsx(p,{game:o.id}),component:ma[o.id]}));function za({language:o,pathname:d,openGame:s,completedIds:g,onComplete:h}){return i.jsx(y,{language:o,games:ba,recordsKey:b,title:{eu:"Jolastu eta hobetu zure marka",es:"Juega y mejora tu marca",ar:"العب وحسّن رقمك"},completedIds:g,onComplete:h,mode:la(d),onModeChange:k=>s(k==="hub"?null:ua[k])})}const z=[{id:"proportions",tone:"blue",title:{eu:"Proportzioak (errepasoa)",es:"Proporciones (repaso)",ar:"التناسبات (مراجعة)"}},{id:"compound",tone:"violet",title:{eu:"Proportzionaltasun konposatua",es:"Proporcionalidad compuesta",ar:"التناسب المركّب"}},{id:"shares",tone:"mustard",title:{eu:"Banaketa proportzionalak",es:"Repartos proporcionales",ar:"التوزيعات التناسبية"}},{id:"percent",tone:"coral",title:{eu:"Ehunekoak",es:"Porcentajes",ar:"النسب المئوية"}},{id:"changes",tone:"green",title:{eu:"Aldakuntzak eta interesa",es:"Variaciones e interés",ar:"التغيّرات والفائدة"}}],e=(o,d,s)=>({eu:o,es:d,ar:s.replace(/\{,\}/g,".")}),n=o=>({eu:o,es:o,ar:o.replace(/\{,\}/g,".")}),ga=[{id:"proportion-review",stage:"proportions",title:e("Arrazoiak eta proportzioak","Razones y proporciones","النسب والتناسبات"),goal:e("Proportzio batean laugarren proportzionala aurkitzea.","Hallar el cuarto proporcional en una proporción.","إيجاد الرابع المتناسب في تناسب."),explanation:e("Bi kantitateren arrazoia haien zatidura da, $\\frac{a}{b}$, eta proportzioa bi arrazoiren berdintasuna, $\\frac{a}{b}=\\frac{c}{d}$. Proportzio batean muturren biderkadura eta erdikoena berdinak dira: $a\\cdot d=b\\cdot c$. Hiru gai ezagutzen badira, laugarrena (laugarren proportzionala) kalkula daiteke: $\\frac{3}{5}=\\frac{45}{x}$ bada, $3\\cdot x=5\\cdot 45=225$ eta $x=75$. Arrazoiak ez du unitaterik behar izaten, baina magnitude desberdinen artekoak bai: 120 km 2 orduan, $60$ km/h.","La razón de dos cantidades es su cociente, $\\frac{a}{b}$, y una proporción es la igualdad de dos razones, $\\frac{a}{b}=\\frac{c}{d}$. En una proporción el producto de extremos es igual al de medios: $a\\cdot d=b\\cdot c$. Si se conocen tres términos, se calcula el cuarto (el cuarto proporcional): si $\\frac{3}{5}=\\frac{45}{x}$, entonces $3\\cdot x=5\\cdot 45=225$ y $x=75$. Una razón entre cantidades de la misma magnitud no lleva unidades, pero entre magnitudes distintas sí: 120 km en 2 horas, $60$ km/h.","نسبة كميتين هي حاصل قسمتهما $\\frac{a}{b}$، والتناسب تساوي نسبتين $\\frac{a}{b}=\\frac{c}{d}$. وفي التناسب حاصل ضرب الطرفين يساوي حاصل ضرب الوسطين: $a\\cdot d=b\\cdot c$. فإذا عُرفت ثلاثة حدود حُسب الرابع (الرابع المتناسب): إذا كان $\\frac{3}{5}=\\frac{45}{x}$ فإن $3\\cdot x=5\\cdot 45=225$ و$x=75$. والنسبة بين كميتين من المقدار نفسه بلا وحدة، أما بين مقدارين مختلفين فلها وحدة: 120 كم في ساعتين، $60$ كم/س."),problem:e("Markosen eta bere aitaren pisuen arrazoia $\\frac{3}{5}$ da. Markosek 45 kg pisatzen ditu. Zenbat pisatzen du aitak?","La razón de los pesos de Marcos y su padre es $\\frac{3}{5}$. Marcos pesa 45 kg. ¿Cuánto pesa su padre?","نسبة وزن ماركوس إلى وزن أبيه $\\frac{3}{5}$. يزن ماركوس 45 كغ. كم يزن أبوه؟"),stepsKind:"steps",steps:[{text:e("Idatzi proportzioa.","Escribe la proporción.","اكتب التناسب."),math:n("$\\frac{3}{5}=\\frac{45}{x}$")},{text:e("Gurutzeko biderkadurak.","Productos cruzados.","الضرب التبادلي."),math:n("$3\\cdot x=5\\cdot 45=225$")},{text:e("Aitak 75 kg.","El padre pesa 75 kg.","يزن الأب 75 كغ."),math:n("$x=225\\mathbin{:}3=75$")}],example:n("$\\frac{a}{b}=\\frac{c}{d}\\ \\to\\ a\\cdot d=b\\cdot c$"),takeaway:e("Laugarren proportzionala: $x=\\frac{b\\cdot c}{a}$.","Cuarto proporcional: $x=\\frac{b\\cdot c}{a}$.","الرابع المتناسب: $x=\\frac{b\\cdot c}{a}$."),figure:o=>i.jsx(ta,{language:o})},{id:"direct-review",stage:"proportions",title:e("Proportzionaltasun zuzena","Proporcionalidad directa","التناسب الطردي"),goal:e("Proportzionaltasun zuzeneko problemak hiruko erregela zuzenaz edo unitatera laburtuz ebaztea.","Resolver problemas de proporcionalidad directa con la regla de tres directa o reduciendo a la unidad.","حلّ مسائل التناسب الطردي بقاعدة الثلاثة الطردية أو بالإرجاع إلى الوحدة."),explanation:e("Bi magnitude zuzenki proportzionalak dira bat bider zenbaki bat egitean bestea ere zenbaki horrekin biderkatzen bada. Orduan balio korrespondenteen zatidura konstantea da: proportzionaltasun-konstantea. Problemak bi eratara ebazten dira: unitatera laburtuz (lehenik 1en balioa, gero nahi dena) edo hiruko erregela zuzenaz, $\\frac{a}{b}=\\frac{c}{x}$. Kontuz: bat handitzean bestea handitzea ez da nahikoa; proportzio berean handitu behar du.","Dos magnitudes son directamente proporcionales si al multiplicar una por un número la otra queda multiplicada por el mismo número. Entonces el cociente de los valores correspondientes es constante: la constante de proporcionalidad. Los problemas se resuelven de dos maneras: reduciendo a la unidad (primero el valor de 1, luego lo que se pide) o con la regla de tres directa, $\\frac{a}{b}=\\frac{c}{x}$. Cuidado: no basta con que al crecer una crezca la otra; tiene que crecer en la misma proporción.","يكون المقداران متناسبين طرديًا إذا ضُرب أحدهما في عدد فضُرب الآخر في العدد نفسه. عندئذ يكون حاصل قسمة القيم المتقابلة ثابتًا: ثابت التناسب. وتُحل المسائل بطريقتين: الإرجاع إلى الوحدة (قيمة الواحد أولًا ثم المطلوب) أو قاعدة الثلاثة الطردية $\\frac{a}{b}=\\frac{c}{x}$. انتبه: لا يكفي أن يزيد أحدهما حين يزيد الآخر؛ يجب أن يزيد بالنسبة نفسها."),problem:e("Txirrindulari batek 200 m egiten ditu 20 segundotan, abiadura berean. Zenbat metro egingo ditu 3 minututan?","Un ciclista recorre 200 m en 20 segundos, a velocidad constante. ¿Cuántos metros recorrerá en 3 minutos?","يقطع دراج 200 م في 20 ثانية بسرعة ثابتة. كم مترًا يقطع في 3 دقائق؟"),stepsKind:"steps",steps:[{text:e("Unitate berean: 3 min = 180 s.","En la misma unidad: 3 min = 180 s.","بالوحدة نفسها: 3 د = 180 ث.")},{text:e("Segundo batean.","En un segundo.","في ثانية واحدة."),math:n("$200\\mathbin{:}20=10$")},{text:e("180 segundotan.","En 180 segundos.","في 180 ثانية."),math:n("$10\\cdot 180=1800$")}],example:n("$\\frac{20}{200}=\\frac{180}{x}\\ \\to\\ x=\\frac{200\\cdot 180}{20}=1800$"),takeaway:e("Zuzena: gehiago → gehiago, eta zatidura konstantea.","Directa: más → más, y el cociente constante.","طردي: أكثر ← أكثر، وحاصل القسمة ثابت."),figure:o=>i.jsx(oa,{language:o})},{id:"inverse-review",stage:"proportions",title:e("Alderantzizko proportzionaltasuna","Proporcionalidad inversa","التناسب العكسي"),goal:e("Alderantzizko proportzionaltasuneko problemak biderkadura konstantea erabiliz ebaztea.","Resolver problemas de proporcionalidad inversa usando el producto constante.","حلّ مسائل التناسب العكسي باستعمال حاصل الضرب الثابت."),explanation:e("Bi magnitude alderantziz proportzionalak dira bat bider zenbaki bat egitean bestea zenbaki horrekin zatitzen bada: bikoitza → erdia. Orduan balio korrespondenteen biderkadura konstantea da. Adibidez, abiadura eta denbora ibilbide berean: 72 km/h-ra 7 orduan egiten bada, ibilbidea $72\\cdot 7=504$ km da, eta 6 orduan egiteko $504\\mathbin{:}6=84$ km/h behar dira. Hiruko erregela alderantzizkoan, lerro bakoitzeko biderkadurak berdintzen dira: $a\\cdot b=c\\cdot x$.","Dos magnitudes son inversamente proporcionales si al multiplicar una por un número la otra queda dividida por ese número: doble → mitad. Entonces el producto de los valores correspondientes es constante. Por ejemplo, la velocidad y el tiempo en un mismo trayecto: si a 72 km/h se tarda 7 horas, el trayecto mide $72\\cdot 7=504$ km, y para hacerlo en 6 horas hacen falta $504\\mathbin{:}6=84$ km/h. En la regla de tres inversa se igualan los productos de cada fila: $a\\cdot b=c\\cdot x$.","يكون المقداران متناسبين عكسيًا إذا ضُرب أحدهما في عدد فقُسم الآخر على ذلك العدد: الضعف ← النصف. عندئذ يكون حاصل ضرب القيم المتقابلة ثابتًا. مثلًا السرعة والزمن في المسار نفسه: إذا استغرق بسرعة 72 كم/س سبع ساعات فطول المسار $72\\cdot 7=504$ كم، ولقطعه في 6 ساعات نحتاج $504\\mathbin{:}6=84$ كم/س. وفي قاعدة الثلاثة العكسية نساوي حاصلي ضرب السطرين: $a\\cdot b=c\\cdot x$."),problem:e("Merkantzia-tren batek 7 ordu behar ditu 72 km/h-ra. Zer abiadurarekin egingo luke 6 ordutan?","Un tren de mercancías tarda 7 horas a 72 km/h. ¿A qué velocidad tendría que ir para tardar 6 horas?","يستغرق قطار بضائع 7 ساعات بسرعة 72 كم/س. بأي سرعة يجب أن يسير ليستغرق 6 ساعات؟"),stepsKind:"steps",steps:[{text:e("Denbora gutxiago → abiadura handiagoa: alderantzizkoa.","Menos tiempo → más velocidad: inversa.","زمن أقل ← سرعة أكبر: عكسي.")},{text:e("Biderkadurak berdindu.","Iguala los productos.","ساوِ حاصلي الضرب."),math:n("$72\\cdot 7=6\\cdot x=504$")},{text:e("Zatitu.","Divide.","اقسم."),math:n("$x=504\\mathbin{:}6=84$")}],example:n("$3\\cdot 15=6\\cdot 7{,}5=9\\cdot 5=45$"),takeaway:e("Alderantzizkoa: gehiago → gutxiago, eta biderkadura konstantea.","Inversa: más → menos, y el producto constante.","عكسي: أكثر ← أقل، وحاصل الضرب ثابت."),figure:o=>i.jsx(ra,{language:o})},{id:"compound-direct",stage:"compound",title:e("Bi erlazio zuzen","Dos relaciones directas","علاقتان طرديتان"),goal:e("Hiru magnitude edo gehiago dituzten problemak ebaztea, erlazio guztiak zuzenak direnean.","Resolver problemas con tres o más magnitudes cuando todas las relaciones son directas.","حلّ مسائل فيها ثلاثة مقادير أو أكثر عندما تكون كل العلاقات طردية."),explanation:e("Proportzionaltasun konposatuan hiru magnitude edo gehiago daude. Ezezaguna duen magnitudea beste bakoitzarekin konparatzen da, banan-banan, besteak aldatu gabe daudela pentsatuz. Igeltsero talde batek, egunean 10 ordu lan eginez, 600 m² horma egin ditu 18 egunetan. Egunean 8 ordu eta 15 egunetan? Ordu gehiago → m² gehiago (zuzena); egun gehiago → m² gehiago (zuzena). Beraz, 600 bider bi zatidurak, biak zuzen jarrita: $600\\cdot\\frac{8}{10}\\cdot\\frac{15}{18}=400$ m².","En la proporcionalidad compuesta intervienen tres o más magnitudes. La magnitud de la incógnita se compara con cada una de las otras, de una en una, imaginando que las demás no cambian. Una cuadrilla de albañiles, trabajando 10 horas al día, ha construido 600 m² de pared en 18 días. ¿Y con 8 horas al día y 15 días? Más horas → más m² (directa); más días → más m² (directa). Así que 600 por los dos cocientes, puestos en el mismo orden: $600\\cdot\\frac{8}{10}\\cdot\\frac{15}{18}=400$ m².","في التناسب المركّب ثلاثة مقادير أو أكثر. نقارن مقدار المجهول بكل مقدار آخر على حدة، ونتخيل أن الباقي لا يتغير. بنت مجموعة بنّائين تعمل 10 ساعات يوميًا 600 م² من الجدار في 18 يومًا. فكم تبني بـ8 ساعات يوميًا و15 يومًا؟ ساعات أكثر ← م² أكثر (طردي)؛ أيام أكثر ← م² أكثر (طردي). إذن 600 في الكسرين بالترتيب نفسه: $600\\cdot\\frac{8}{10}\\cdot\\frac{15}{18}=400$ م²."),problem:e("5 makinak, egunean 6 ordu, 1500 pieza egiten dituzte. Zenbat pieza 4 makinak egunean 9 ordu?","5 máquinas, 6 horas al día, fabrican 1500 piezas. ¿Cuántas piezas fabrican 4 máquinas 9 horas al día?","5 آلات تعمل 6 ساعات يوميًا تصنع 1500 قطعة. كم قطعة تصنع 4 آلات تعمل 9 ساعات يوميًا؟"),stepsKind:"steps",steps:[{text:e("Makina gehiago → pieza gehiago: zuzena.","Más máquinas → más piezas: directa.","آلات أكثر ← قطع أكثر: طردي."),math:n("$\\frac{4}{5}$")},{text:e("Ordu gehiago → pieza gehiago: zuzena.","Más horas → más piezas: directa.","ساعات أكثر ← قطع أكثر: طردي."),math:n("$\\frac{9}{6}$")},{text:e("Biderkatu.","Multiplica.","اضرب."),math:n("$1500\\cdot\\frac{4}{5}\\cdot\\frac{9}{6}=1800$")}],example:n("$600\\cdot\\frac{8}{10}\\cdot\\frac{15}{18}=400$"),takeaway:e("Magnitude bakoitza bere aldetik konparatu; zuzenak: zatidura berria/zaharra.","Compara cada magnitud por separado; las directas: cociente nuevo/viejo.","قارن كل مقدار على حدة؛ الطردية: الكسر الجديد/القديم."),figure:o=>i.jsx(R,{language:o})},{id:"compound-mixed",stage:"compound",title:e("Erlazio zuzenak eta alderantzizkoak","Relaciones directas e inversas","علاقات طردية وعكسية"),goal:e("Proportzionaltasun konposatuko problemak ebaztea erlazio zuzenak eta alderantzizkoak nahasten direnean.","Resolver problemas de proporcionalidad compuesta que mezclan relaciones directas e inversas.","حلّ مسائل التناسب المركّب التي تمزج علاقات طردية وعكسية."),explanation:e("Erlazio bat alderantzizkoa denean, haren zatidura buruz behera jartzen da (zaharra/berria). Nekazari batek 294 kg pentsu behar izan ditu 15 behi 7 egunez elikatzeko. 840 kg-rekin, zenbat egun elika ditzake 10 behi? Pentsu gehiago → egun gehiago: zuzena, $\\frac{840}{294}$. Behi gutxiago → egun gehiago: alderantzizkoa, $\\frac{15}{10}$. Beraz $7\\cdot\\frac{840}{294}\\cdot\\frac{15}{10}=30$ egun. Galdera bera beti: «besteak berdin badaude, hau handitzean ezezaguna handitu ala txikitu egiten da?»","Cuando una relación es inversa, su cociente se pone al revés (viejo/nuevo). Un granjero ha necesitado 294 kg de pienso para alimentar a 15 vacas durante 7 días. Con 840 kg, ¿cuántos días puede alimentar a 10 vacas? Más pienso → más días: directa, $\\frac{840}{294}$. Menos vacas → más días: inversa, $\\frac{15}{10}$. Así que $7\\cdot\\frac{840}{294}\\cdot\\frac{15}{10}=30$ días. La pregunta es siempre la misma: «si lo demás no cambia, al crecer esta, ¿la incógnita crece o decrece?»","إذا كانت العلاقة عكسية نقلب كسرها (القديم/الجديد). احتاج مزارع 294 كغ من العلف ليطعم 15 بقرة 7 أيام. فبـ840 كغ، كم يومًا يطعم 10 أبقار؟ علف أكثر ← أيام أكثر: طردي، $\\frac{840}{294}$. أبقار أقل ← أيام أكثر: عكسي، $\\frac{15}{10}$. إذن $7\\cdot\\frac{840}{294}\\cdot\\frac{15}{10}=30$ يومًا. والسؤال دائمًا: «إذا بقي الباقي ثابتًا، فحين يزيد هذا المقدار هل يزيد المجهول أم ينقص؟»"),problem:e("Hondeamakina batek, egunean 10 ordu, 1000 m-ko zanga egiten du 8 egunetan. Zenbat egun beharko ditu 600 m-ko zanga egiteko, egunean 12 ordu?","Una excavadora, trabajando 10 horas al día, abre una zanja de 1000 m en 8 días. ¿Cuánto tardará en abrir una de 600 m trabajando 12 horas al día?","تحفر حفّارة تعمل 10 ساعات يوميًا خندقًا طوله 1000 م في 8 أيام. كم يومًا تحتاج لخندق طوله 600 م إذا عملت 12 ساعة يوميًا؟"),stepsKind:"steps",steps:[{text:e("Metro gutxiago → egun gutxiago: zuzena.","Menos metros → menos días: directa.","أمتار أقل ← أيام أقل: طردي."),math:n("$\\frac{600}{1000}$")},{text:e("Ordu gehiago → egun gutxiago: alderantzizkoa.","Más horas → menos días: inversa.","ساعات أكثر ← أيام أقل: عكسي."),math:n("$\\frac{10}{12}$")},{text:e("Biderkatu.","Multiplica.","اضرب."),math:n("$8\\cdot\\frac{600}{1000}\\cdot\\frac{10}{12}=4$")}],example:n("$7\\cdot\\frac{840}{294}\\cdot\\frac{15}{10}=30$"),takeaway:e("Zuzena: berria/zaharra. Alderantzizkoa: zaharra/berria.","Directa: nuevo/viejo. Inversa: viejo/nuevo.","الطردي: الجديد/القديم. العكسي: القديم/الجديد."),figure:o=>i.jsx(M,{language:o})},{id:"compound-unit",stage:"compound",title:e("Unitatera laburtuz, urratsez urrats","Reduciendo a la unidad, paso a paso","بالإرجاع إلى الوحدة خطوة خطوة"),goal:e("Proportzionaltasun konposatuko problemak magnitude bat aldi berean aldatuz ebaztea.","Resolver problemas de proporcionalidad compuesta cambiando una magnitud cada vez.","حلّ مسائل التناسب المركّب بتغيير مقدار واحد في كل مرة."),explanation:e("Formula bat gogoratu beharrean, magnitude bat aldi berean alda daiteke, gainerakoak finko utzita, proportzionaltasun soileko pausoak bezala. Hiru aspertsorek, 1,5 l/s bakoitzak, ur-biltegia 8 orduan husten dute. Lau aspertsorek 0,9 l/s-rekin? Aspertsore bakarra: 3 aldiz denbora gehiago, 24 h. Lau: 4 aldiz gutxiago, 6 h (1,5 l/s-rekin). Emari txikiagoarekin denbora gehiago: $6\\cdot 1{,}5\\mathbin{:}0{,}9=10$ h. Edo ur osoarekin: $3\\cdot 1{,}5=4{,}5$ l/s eta $4\\cdot 0{,}9=3{,}6$ l/s; $4{,}5\\cdot 8=3{,}6\\cdot x$, $x=10$ h.","En lugar de recordar una fórmula, se puede cambiar una magnitud cada vez, dejando fijas las demás, como pasos de proporcionalidad simple. Tres aspersores de 1,5 l/s cada uno vacían un depósito en 8 horas. ¿Y cuatro aspersores de 0,9 l/s? Con un solo aspersor: tres veces más tiempo, 24 h. Con cuatro: cuatro veces menos, 6 h (a 1,5 l/s). Con menos caudal, más tiempo: $6\\cdot 1{,}5\\mathbin{:}0{,}9=10$ h. O con el agua total: $3\\cdot 1{,}5=4{,}5$ l/s y $4\\cdot 0{,}9=3{,}6$ l/s; $4{,}5\\cdot 8=3{,}6\\cdot x$, $x=10$ h.","بدل حفظ صيغة يمكن تغيير مقدار واحد في كل مرة مع تثبيت الباقي، كخطوات تناسب بسيط. ثلاث رشّاشات تدفق كل منها 1.5 ل/ث تفرغ خزانًا في 8 ساعات. فماذا عن أربع رشّاشات تدفقها 0.9 ل/ث؟ برشّاش واحد: ثلاثة أضعاف الزمن، 24 س. وبأربعة: أقل بأربع مرات، 6 س (بتدفق 1.5). وبتدفق أقل زمن أكثر: $6\\cdot 1{,}5\\mathbin{:}0{,}9=10$ س. أو بالماء الكلي: $3\\cdot 1{,}5=4{,}5$ ل/ث و$4\\cdot 0{,}9=3{,}6$ ل/ث؛ $4{,}5\\cdot 8=3{,}6\\cdot x$، $x=10$ س."),problem:e("6 lagunek 4 egunetan 72 € gastatzen dituzte janarian. Zenbat gastatuko dute 9 lagunek 5 egunetan?","6 amigos gastan 72 € en comida en 4 días. ¿Cuánto gastarán 9 amigos en 5 días?","6 أصدقاء ينفقون 72 € على الطعام في 4 أيام. كم ينفق 9 أصدقاء في 5 أيام؟"),stepsKind:"steps",steps:[{text:e("Lagun batek, 4 egunetan.","Un amigo, en 4 días.","صديق واحد في 4 أيام."),math:n("$72\\mathbin{:}6=12$")},{text:e("Lagun batek, egun batean.","Un amigo, en un día.","صديق واحد في يوم."),math:n("$12\\mathbin{:}4=3$")},{text:e("9 lagunek, 5 egunetan.","9 amigos, en 5 días.","9 أصدقاء في 5 أيام."),math:n("$3\\cdot 9\\cdot 5=135$")}],example:n("$4{,}5\\cdot 8=3{,}6\\cdot x\\ \\to\\ x=36\\mathbin{:}3{,}6=10$"),takeaway:e("Magnitude bat aldi berean: bakoitza proportzionaltasun soil bat da.","Una magnitud cada vez: cada paso es una proporcionalidad simple.","مقدار واحد في كل مرة: كل خطوة تناسب بسيط."),figure:o=>i.jsx(U,{language:o})},{id:"direct-share",stage:"shares",title:e("Banaketa zuzenki proportzionala","Reparto directamente proporcional","التوزيع الطردي"),goal:e("Kantitate bat zenbaki batzuekiko zuzenki proportzionalak diren zatitan banatzea.","Repartir una cantidad en partes directamente proporcionales a unos números.","توزيع كمية إلى أجزاء متناسبة طرديًا مع أعداد معطاة."),explanation:e("Banaketa zuzenki proportzionalean, zenbaki handiagoari zati handiagoa dagokio. Batu zenbakiak, zatitu kantitatea batura horren artean (zati bakoitzaren balioa, $p$) eta biderkatu zenbaki bakoitza $p$-z. 180 banatu 2, 5 eta 8rekiko zuzenki proportzionalki: $2+5+8=15$ zati; $180\\mathbin{:}15=12$; zatiak $2\\cdot 12=24$, $5\\cdot 12=60$ eta $8\\cdot 12=96$. Egiaztatu: $24+60+96=180$.","En un reparto directamente proporcional, al número mayor le toca la parte mayor. Suma los números, divide la cantidad entre esa suma (el valor de cada parte, $p$) y multiplica cada número por $p$. Reparte 180 en partes directamente proporcionales a 2, 5 y 8: $2+5+8=15$ partes; $180\\mathbin{:}15=12$; las partes son $2\\cdot 12=24$, $5\\cdot 12=60$ y $8\\cdot 12=96$. Comprueba: $24+60+96=180$.","في التوزيع الطردي يأخذ العدد الأكبر الجزء الأكبر. اجمع الأعداد، واقسم الكمية على المجموع (قيمة الجزء الواحد $p$)، ثم اضرب كل عدد في $p$. وزّع 180 طرديًا على 2 و5 و8: $2+5+8=15$ جزءًا؛ $180\\mathbin{:}15=12$؛ الأجزاء $2\\cdot 12=24$ و$5\\cdot 12=60$ و$8\\cdot 12=96$. تحقّق: $24+60+96=180$."),problem:e("Hiru lagunek 3 €, 5 € eta 7 € jarri zituzten loteria-zenbaki batean, eta 450 € irabazi dituzte. Zenbat dagokio bakoitzari?","Tres amigos pusieron 3 €, 5 € y 7 € en un número de lotería y han ganado 450 €. ¿Cuánto le toca a cada uno?","وضع ثلاثة أصدقاء 3 € و5 € و7 € في رقم يانصيب وربحوا 450 €. كم نصيب كل واحد؟"),stepsKind:"steps",steps:[{text:e("Zatiak guztira.","Partes en total.","مجموع الأجزاء."),math:n("$3+5+7=15$")},{text:e("Zati baten balioa.","Valor de una parte.","قيمة الجزء الواحد."),math:n("$450\\mathbin{:}15=30$")},{text:e("Bakoitzari.","A cada uno.","لكل واحد."),math:n("$90,\\ 150,\\ 210$")}],example:n("$180\\mathbin{:}(2+5+8)=12\\ \\to\\ 24,\\ 60,\\ 96$"),takeaway:e("Zuzena: kantitatea : batura, gero bider zenbaki bakoitza.","Directo: cantidad : suma, y luego por cada número.","الطردي: الكمية : المجموع ثم في كل عدد."),figure:o=>i.jsx(K,{language:o})},{id:"share-problems",stage:"shares",title:e("Banaketak problemetan eta zatikiekin","Repartos en problemas y con fracciones","التوزيع في المسائل وبالكسور"),goal:e("Banaketa proportzionalak egunekin, orduekin edo zatikiekin ebaztea.","Resolver repartos proporcionales con días, horas o fracciones.","حلّ توزيعات تناسبية بالأيام أو الساعات أو الكسور."),explanation:e("Problemetan, zenbakiak sarritan egunak, orduak edo jarritako dirua dira. Hiru familiak apartamentu bat alokatu dute 20 egunez 1200 €-an: lehenengoak 7 egun, bigarrenak 6 eta hirugarrenak 7. Egun bakoitzak $1200\\mathbin{:}20=60$ € balio du: 420 €, 360 € eta 420 €. Zenbakiak zatikiak direnean, idatzi izendatzaile berarekin eta banatu zenbakitzaileen arabera: $\\frac{1}{2},\\frac{1}{3},\\frac{1}{4}=\\frac{6}{12},\\frac{4}{12},\\frac{3}{12}$, beraz 6, 4 eta 3rekiko banaketa da.","En los problemas, los números suelen ser días, horas o el dinero puesto. Tres familias alquilan un apartamento 20 días por 1200 €: la primera está 7 días, la segunda 6 y la tercera 7. Cada día vale $1200\\mathbin{:}20=60$ €: 420 €, 360 € y 420 €. Cuando los números son fracciones, escríbelas con el mismo denominador y reparte según los numeradores: $\\frac{1}{2},\\frac{1}{3},\\frac{1}{4}=\\frac{6}{12},\\frac{4}{12},\\frac{3}{12}$, así que es un reparto proporcional a 6, 4 y 3.","في المسائل تكون الأعداد غالبًا أيامًا أو ساعات أو مالًا مدفوعًا. استأجرت ثلاث عائلات شقة 20 يومًا بـ1200 €: الأولى 7 أيام والثانية 6 والثالثة 7. قيمة اليوم $1200\\mathbin{:}20=60$ €: 420 € و360 € و420 €. وإذا كانت الأعداد كسورًا فاكتبها بالمقام نفسه ووزّع حسب البسوط: $\\frac{1}{2},\\frac{1}{3},\\frac{1}{4}=\\frac{6}{12},\\frac{4}{12},\\frac{3}{12}$، فهو توزيع متناسب مع 6 و4 و3."),problem:e("Banatu 130 zuzenki proportzionalki $\\frac{1}{2}$, $\\frac{1}{3}$ eta $\\frac{1}{4}$-rekiko.","Reparte 130 en partes directamente proporcionales a $\\frac{1}{2}$, $\\frac{1}{3}$ y $\\frac{1}{4}$.","وزّع 130 طرديًا على $\\frac{1}{2}$ و$\\frac{1}{3}$ و$\\frac{1}{4}$."),stepsKind:"steps",steps:[{text:e("Izendatzaile bera.","Mismo denominador.","المقام نفسه."),math:n("$\\frac{6}{12},\\ \\frac{4}{12},\\ \\frac{3}{12}$")},{text:e("6, 4 eta 3rekiko: 13 zati.","Proporcional a 6, 4 y 3: 13 partes.","متناسب مع 6 و4 و3: 13 جزءًا."),math:n("$130\\mathbin{:}13=10$")},{text:e("Zatiak.","Las partes.","الأجزاء."),math:n("$60,\\ 40,\\ 30$")}],example:n("$1200\\mathbin{:}20=60\\ \\to\\ 420,\\ 360,\\ 420$"),takeaway:e("Zatikiak: izendatzaile bera, eta banatu zenbakitzaileen arabera.","Fracciones: mismo denominador, y reparte según los numeradores.","الكسور: المقام نفسه ثم التوزيع حسب البسوط."),figure:o=>i.jsx(T,{language:o})},{id:"inverse-share",stage:"shares",title:e("Banaketa alderantziz proportzionala","Reparto inversamente proporcional","التوزيع العكسي"),goal:e("Kantitate bat zenbaki batzuekiko alderantziz proportzionalak diren zatitan banatzea.","Repartir una cantidad en partes inversamente proporcionales a unos números.","توزيع كمية إلى أجزاء متناسبة عكسيًا مع أعداد معطاة."),explanation:e("Alderantzizko banaketan, zenbaki handiagoari zati txikiagoa dagokio. Zenbakiekiko alderantziz proportzionala banatzea haien alderantzizkoekiko zuzenki banatzea da: 2, 3 eta 5ekiko alderantziz = $\\frac{1}{2}$, $\\frac{1}{3}$ eta $\\frac{1}{5}$-ekiko zuzenki. Izendatzaile berarekin $\\frac{15}{30},\\frac{10}{30},\\frac{6}{30}$: 15, 10 eta 6rekiko banaketa. 620 banatuz: $15+10+6=31$; $620\\mathbin{:}31=20$; zatiak 300, 200 eta 120. Telebista-lehiaketa bateko saria postuarekiko alderantziz banatzen da: lehenengoak gehien.","En un reparto inverso, al número mayor le toca la parte menor. Repartir de forma inversamente proporcional a unos números es repartir de forma directa a sus inversos: inversamente a 2, 3 y 5 = directamente a $\\frac{1}{2}$, $\\frac{1}{3}$ y $\\frac{1}{5}$. Con el mismo denominador, $\\frac{15}{30},\\frac{10}{30},\\frac{6}{30}$: reparto proporcional a 15, 10 y 6. Repartiendo 620: $15+10+6=31$; $620\\mathbin{:}31=20$; las partes son 300, 200 y 120. El premio de un concurso se reparte de forma inversa al puesto: el primero, el que más.","في التوزيع العكسي يأخذ العدد الأكبر الجزء الأصغر. التوزيع عكسيًا على أعداد هو التوزيع طرديًا على مقلوباتها: عكسيًا على 2 و3 و5 = طرديًا على $\\frac{1}{2}$ و$\\frac{1}{3}$ و$\\frac{1}{5}$. وبالمقام نفسه $\\frac{15}{30},\\frac{10}{30},\\frac{6}{30}$: توزيع متناسب مع 15 و10 و6. ولتوزيع 620: $15+10+6=31$؛ $620\\mathbin{:}31=20$؛ الأجزاء 300 و200 و120. وتوزَّع جائزة مسابقة عكسيًا مع الترتيب: الأول يأخذ الأكثر."),problem:e("22 000 €-ko saria hiru lehenengoen artean banatzen da, postuarekiko (1, 2 eta 3) alderantziz proportzionalki. Zenbat irabazten du bakoitzak?","Un premio de 22 000 € se reparte entre los tres primeros de forma inversamente proporcional al puesto (1, 2 y 3). ¿Cuánto gana cada uno?","تُوزَّع جائزة 22000 € على الثلاثة الأوائل عكسيًا مع الترتيب (1 و2 و3). كم يربح كل واحد؟"),stepsKind:"steps",steps:[{text:e("Alderantzizkoak, izendatzaile berarekin.","Los inversos, con el mismo denominador.","المقلوبات بالمقام نفسه."),math:n("$\\frac{6}{6},\\ \\frac{3}{6},\\ \\frac{2}{6}$")},{text:e("6, 3 eta 2rekiko: 11 zati.","Proporcional a 6, 3 y 2: 11 partes.","متناسب مع 6 و3 و2: 11 جزءًا."),math:n("$22\\,000\\mathbin{:}11=2000$")},{text:e("Sariak.","Los premios.","الجوائز."),math:n("$12\\,000,\\ 6000,\\ 4000$")}],example:n("$620\\mathbin{:}(15+10+6)=20\\ \\to\\ 300,\\ 200,\\ 120$"),takeaway:e("Alderantzizkoa: banatu alderantzizkoekiko zuzenki.","Inverso: reparte directamente a los inversos.","العكسي: وزّع طرديًا على المقلوبات."),figure:o=>i.jsx(L,{language:o})},{id:"percent-forms",stage:"percent",title:e("Ehunekoa hamartar gisa","El porcentaje como decimal","النسبة المئوية عددًا عشريًا"),goal:e("Ehuneko bat hamartar gisa idaztea eta kantitate baten ehunekoa biderketa bakar batez kalkulatzea, % 100etik gorakoak barne.","Escribir un porcentaje como decimal y calcular el porcentaje de una cantidad con una sola multiplicación, también por encima del 100 %.","كتابة النسبة المئوية عددًا عشريًا وحساب نسبة من كمية بضربة واحدة، حتى فوق 100٪."),explanation:e("Ehuneko bat 100 izendatzailea duen zatiki bat da, eta hamartar gisa idatz daiteke: % 12 = $\\frac{12}{100}=0{,}12$; % 8 = $0{,}08$; % 2,5 = $0{,}025$. Kantitate baten ehunekoa kalkulatzeko, nahikoa da hamartarraz biderkatzea: 750en % 12 = $750\\cdot 0{,}12=90$. Ehunekoak 100 baino handiagoak ere izan daitezke: % 150 = $1{,}5$, eta 40ren % 150 = $40\\cdot 1{,}5=60$, kantitatea bera baino gehiago. Kontuz: % 5 ez da $0{,}5$, $0{,}05$ baizik.","Un porcentaje es una fracción de denominador 100 y se puede escribir como decimal: 12 % = $\\frac{12}{100}=0{,}12$; 8 % = $0{,}08$; 2,5 % = $0{,}025$. Para calcular el porcentaje de una cantidad basta multiplicar por el decimal: 12 % de 750 = $750\\cdot 0{,}12=90$. Los porcentajes también pueden pasar de 100: 150 % = $1{,}5$, y el 150 % de 40 = $40\\cdot 1{,}5=60$, más que la cantidad. Cuidado: el 5 % no es $0{,}5$, sino $0{,}05$.","النسبة المئوية كسر مقامه 100 ويمكن كتابتها عددًا عشريًا: 12٪ = $\\frac{12}{100}=0{,}12$؛ 8٪ = $0{,}08$؛ 2.5٪ = $0{,}025$. ولحساب نسبة من كمية يكفي الضرب في العدد العشري: 12٪ من 750 = $750\\cdot 0{,}12=90$. وقد تزيد النسبة على 100: 150٪ = $1{,}5$، و150٪ من 40 = $40\\cdot 1{,}5=60$، أكثر من الكمية. انتبه: 5٪ ليست $0{,}5$ بل $0{,}05$."),problem:e("Kalkulatu 200en % 115.","Calcula el 115 % de 200.","احسب 115٪ من 200."),stepsKind:"steps",steps:[{text:e("Hamartar gisa.","Como decimal.","عددًا عشريًا."),math:n("$115\\mathbin{:}100=1{,}15$")},{text:e("Biderkatu.","Multiplica.","اضرب."),math:n("$200\\cdot 1{,}15=230$")}],example:n("$0{,}35\\quad 0{,}08\\quad 1{,}2\\quad 0{,}025$"),takeaway:e("% $p$ = $p\\mathbin{:}100$; kantitatea bider hamartarra.","$p$ % = $p\\mathbin{:}100$; la cantidad por el decimal.","$p$٪ = $p\\mathbin{:}100$؛ الكمية في العدد العشري."),figure:o=>i.jsx(H,{language:o})},{id:"percent-total",stage:"percent",title:e("Hasierako kantitatea","La cantidad inicial","الكمية الأصلية"),goal:e("Zati bat eta haren ehunekoa jakinda, osoa kalkulatzea.","Calcular el total conociendo una parte y su porcentaje.","حساب الكل بمعرفة جزء ونسبته المئوية."),explanation:e("Batzuetan zatia eta ehunekoa ezagutzen dira, eta osoa falta da. «$x$-ren % 12 = 42» idazten bada, $x\\cdot 0{,}12=42$, beraz $x=42\\mathbin{:}0{,}12=350$: zatia zati hamartarra. Hiruko erregelaz ere egin daiteke: % 12 → 42, % 100 → $x$. Egiaztatu beti: 350en % 12 = 42. Gaur entsegura 6 musikari falta dira, taldearen % 20: taldeak $6\\mathbin{:}0{,}20=30$ musikari ditu.","A veces se conocen la parte y el porcentaje, y falta el total. Si se escribe «el 12 % de $x$ es 42», $x\\cdot 0{,}12=42$, así que $x=42\\mathbin{:}0{,}12=350$: la parte entre el decimal. También con regla de tres: 12 % → 42, 100 % → $x$. Comprueba siempre: el 12 % de 350 es 42. Hoy faltan al ensayo 6 músicos, el 20 % de la banda: la banda tiene $6\\mathbin{:}0{,}20=30$ músicos.","أحيانًا نعرف الجزء والنسبة ويبقى الكل مجهولًا. إذا كتبنا «12٪ من $x$ تساوي 42» فإن $x\\cdot 0{,}12=42$، إذن $x=42\\mathbin{:}0{,}12=350$: الجزء على العدد العشري. ويمكن بقاعدة الثلاثة: 12٪ ← 42، و100٪ ← $x$. تحقّق دائمًا: 12٪ من 350 تساوي 42. غاب اليوم عن التدريب 6 موسيقيين، أي 20٪ من الفرقة: في الفرقة $6\\mathbin{:}0{,}20=30$ موسيقيًا."),problem:e("Artalde batean 14 ardi beltz daude, guztien % 8. Zenbat ardi ditu artaldeak?","En un rebaño hay 14 ovejas negras, el 8 % del total. ¿Cuántas ovejas tiene el rebaño?","في قطيع 14 نعجة سوداء، أي 8٪ من الكل. كم نعجة في القطيع؟"),stepsKind:"steps",steps:[{text:e("Idatzi ekuazioa.","Escribe la ecuación.","اكتب المعادلة."),math:n("$x\\cdot 0{,}08=14$")},{text:e("Zatitu hamartarraz.","Divide entre el decimal.","اقسم على العدد العشري."),math:n("$x=14\\mathbin{:}0{,}08=175$")}],example:n("$x\\cdot 0{,}12=42\\ \\to\\ x=42\\mathbin{:}0{,}12=350$"),takeaway:e("Osoa = zatia : hamartarra.","Total = parte : decimal.","الكل = الجزء : العدد العشري."),figure:o=>i.jsx(S,{language:o})},{id:"percent-which",stage:"percent",title:e("Zer ehuneko? Aldakuntzaren ehunekoa","¿Qué porcentaje? El porcentaje de variación","أي نسبة؟ نسبة التغيّر"),goal:e("Zati batek osoaren zer ehuneko den eta kantitate batek zer ehuneko igo edo jaitsi den kalkulatzea.","Calcular qué porcentaje es una parte del total y en qué porcentaje ha subido o bajado una cantidad.","حساب نسبة جزء من الكل ونسبة ارتفاع كمية أو انخفاضها."),explanation:e("Ehunekoa = zatia : osoa · 100. Adrianok 200 € zituen eta 50 € gastatu ditu: $50\\mathbin{:}200\\cdot 100=25$, % 25. Kantitate bat aldatzen denean, kalkulatu amaierakoa hasierakoaren zer ehuneko den: salmentak 2500etik 2800era igo dira, $2800\\mathbin{:}2500\\cdot 100=112$, beraz % 112 → % 12 igo dira. Edo kalkulatu aldaketa eta zatitu hasierakoaz: $300\\mathbin{:}2500\\cdot 100=12$. Beti hasierako kantitatearekiko!","Porcentaje = parte : total · 100. Adriano tenía 200 € y ha gastado 50 €: $50\\mathbin{:}200\\cdot 100=25$, el 25 %. Cuando una cantidad cambia, calcula qué porcentaje es la final de la inicial: las ventas han pasado de 2500 a 2800, $2800\\mathbin{:}2500\\cdot 100=112$, es decir, el 112 % → han subido un 12 %. O calcula el cambio y divide entre la inicial: $300\\mathbin{:}2500\\cdot 100=12$. ¡Siempre respecto de la cantidad inicial!","النسبة = الجزء : الكل · 100. كان مع أدريانو 200 € وأنفق 50 €: $50\\mathbin{:}200\\cdot 100=25$، أي 25٪. وإذا تغيّرت كمية فاحسب نسبة النهائية إلى الأصلية: ارتفعت المبيعات من 2500 إلى 2800، $2800\\mathbin{:}2500\\cdot 100=112$، أي 112٪ ← ارتفعت 12٪. أو احسب التغيّر واقسمه على الأصلية: $300\\mathbin{:}2500\\cdot 100=12$. دائمًا بالنسبة إلى الكمية الأصلية!"),problem:e("Hiru urte lehenago 280 000 € balio zuen etxe bat 350 000 €-an saldu da. Zer ehuneko igo da?","Una vivienda que costó 280 000 € hace tres años se ha vendido por 350 000 €. ¿Qué porcentaje ha subido?","بيع منزل بـ350000 € وكان ثمنه قبل ثلاث سنوات 280000 €. بأي نسبة ارتفع؟"),stepsKind:"steps",steps:[{text:e("Amaierakoa : hasierakoa · 100.","Final : inicial · 100.","النهائية : الأصلية · 100."),math:n("$350\\,000\\mathbin{:}280\\,000\\cdot 100=125$")},{text:e("% 125 → % 25 igo da.","125 % → ha subido un 25 %.","125٪ ← ارتفع 25٪.")}],example:n("$50\\mathbin{:}200\\cdot 100=25$"),takeaway:e("Ehunekoa = zatia : osoa · 100. Aldakuntza: hasierakoarekiko.","Porcentaje = parte : total · 100. Variación: respecto de la inicial.","النسبة = الجزء : الكل · 100. والتغيّر: بالنسبة إلى الأصلية."),figure:o=>i.jsx(F,{language:o})},{id:"index",stage:"changes",title:e("Aldakuntza-indizea","El índice de variación","مؤشر التغيّر"),goal:e("Igoerak eta beherapenak indize batez biderkatuz kalkulatzea, eta hasierako kantitatea indizeaz zatituz.","Calcular aumentos y disminuciones multiplicando por un índice, y la cantidad inicial dividiendo entre él.","حساب الزيادات والتخفيضات بالضرب في مؤشر، والكمية الأصلية بالقسمة عليه."),explanation:e("Kantitate bat % $p$ igotzean, amaierakoa % $(100+p)$ da: biderkatu $1+\\frac{p}{100}$ indizeaz (% 12 igo → $\\cdot 1{,}12$). % $p$ jaistean, % $(100-p)$: biderkatu $1-\\frac{p}{100}$-z (% 15 merkatu → $\\cdot 0{,}85$). Amaierako = hasierako · indizea, beraz hasierako = amaierako : indizea. % 15 merkatutako gona batek 36,55 € balio du: $36{,}55\\mathbin{:}0{,}85=43$ € balio zuen. Kontuz: hasierakoa ez da amaierakoari % 15 gehituz lortzen.","Al aumentar una cantidad un $p$ %, la final es el $(100+p)$ %: multiplica por el índice $1+\\frac{p}{100}$ (sube un 12 % → $\\cdot 1{,}12$). Al disminuir un $p$ %, el $(100-p)$ %: multiplica por $1-\\frac{p}{100}$ (rebaja del 15 % → $\\cdot 0{,}85$). Final = inicial · índice, así que inicial = final : índice. Una falda rebajada un 15 % cuesta 36,55 €: costaba $36{,}55\\mathbin{:}0{,}85=43$ €. Cuidado: la inicial no se obtiene sumando a la final un 15 %.","عند زيادة كمية بنسبة $p$٪ تصبح النهائية $(100+p)$٪: اضرب في المؤشر $1+\\frac{p}{100}$ (زيادة 12٪ ← $\\cdot 1{,}12$). وعند إنقاصها $p$٪ تصبح $(100-p)$٪: اضرب في $1-\\frac{p}{100}$ (تخفيض 15٪ ← $\\cdot 0{,}85$). النهائية = الأصلية · المؤشر، إذن الأصلية = النهائية : المؤشر. تنورة مخفّضة 15٪ ثمنها 36.55 €: كان ثمنها $36{,}55\\mathbin{:}0{,}85=43$ €. انتبه: لا نحصل على الأصلية بإضافة 15٪ إلى النهائية."),problem:e("Martari soldata % 10 igo diote eta orain 1760 € irabazten ditu. Zenbat irabazten zuen lehen?","A Marta le han subido el sueldo un 10 % y ahora gana 1760 €. ¿Cuánto ganaba antes?","رُفع راتب مارتا 10٪ فصارت تربح 1760 €. كم كانت تربح قبل ذلك؟"),stepsKind:"steps",steps:[{text:e("Indizea: % 110.","Índice: el 110 %.","المؤشر: 110٪."),math:n("$1{,}10$")},{text:e("Hasierakoa = amaierakoa : indizea.","Inicial = final : índice.","الأصلية = النهائية : المؤشر."),math:n("$1760\\mathbin{:}1{,}1=1600$")}],example:n("$2500\\cdot 1{,}12=2800\\qquad 2800\\mathbin{:}1{,}12=2500$"),takeaway:e("Igo: $\\cdot(1+\\frac{p}{100})$. Jaitsi: $\\cdot(1-\\frac{p}{100})$. Atzera: zatitu.","Subir: $\\cdot(1+\\frac{p}{100})$. Bajar: $\\cdot(1-\\frac{p}{100})$. Hacia atrás: divide.","زيادة: $\\cdot(1+\\frac{p}{100})$. تخفيض: $\\cdot(1-\\frac{p}{100})$. للرجوع: اقسم."),figure:o=>i.jsx(O,{language:o})},{id:"chained",stage:"changes",title:e("Ehuneko kateatuak","Porcentajes encadenados","النسب المتتالية"),goal:e("Bata bestearen atzetik egiten diren igoerak eta beherapenak indizeak biderkatuz kalkulatzea.","Calcular aumentos y disminuciones sucesivos multiplicando los índices.","حساب زيادات وتخفيضات متتالية بضرب المؤشرات."),explanation:e("Bi aldaketa jarraian egiten direnean, bigarrena lehenaren ondoren dagoen kantitateari aplikatzen zaio, ez hasierakoari. Horregatik indizeak biderkatzen dira, ez ehunekoak batzen. % 10 igo eta gero % 10 jaitsi: $1{,}1\\cdot 0{,}9=0{,}99$, beraz % 1 galtzen da, ez da hasierara itzultzen! 200 € balio duen jaka bat % 20 garestitu eta gero % 25 merkatzen da: $200\\cdot 1{,}2\\cdot 0{,}75=180$ €. Indize osoa $0{,}9$ da: % 10 merkeago, guztira.","Cuando se hacen dos cambios seguidos, el segundo se aplica a la cantidad que queda tras el primero, no a la inicial. Por eso se multiplican los índices, no se suman los porcentajes. Subir un 10 % y luego bajar un 10 %: $1{,}1\\cdot 0{,}9=0{,}99$, así que se pierde un 1 %: ¡no se vuelve al principio! Una chaqueta de 200 € sube un 20 % y luego baja un 25 %: $200\\cdot 1{,}2\\cdot 0{,}75=180$ €. El índice total es $0{,}9$: un 10 % más barata en total.","عند إجراء تغيّرين متتاليين يُطبَّق الثاني على الكمية الناتجة عن الأول لا على الأصلية. لذلك نضرب المؤشرات ولا نجمع النسب. زيادة 10٪ ثم تخفيض 10٪: $1{,}1\\cdot 0{,}9=0{,}99$، أي خسارة 1٪: لا نعود إلى البداية! سترة ثمنها 200 € ترتفع 20٪ ثم تنخفض 25٪: $200\\cdot 1{,}2\\cdot 0{,}75=180$ €. والمؤشر الكلي $0{,}9$: أرخص بـ10٪ إجمالًا."),problem:e("500 €-ko bizikleta bat % 20 merkatu dute, eta gero beste % 10. Zenbat balio du orain?","Una bici de 500 € se rebaja un 20 % y después otro 10 %. ¿Cuánto cuesta ahora?","دراجة ثمنها 500 € خُفّضت 20٪ ثم 10٪ أخرى. كم ثمنها الآن؟"),stepsKind:"steps",steps:[{text:e("Indizeak.","Los índices.","المؤشرات."),math:n("$0{,}8\\cdot 0{,}9=0{,}72$")},{text:e("Biderkatu.","Multiplica.","اضرب."),math:n("$500\\cdot 0{,}72=360$")},{text:e("% 28 merkeago, ez % 30.","Un 28 % más barata, no un 30 %.","أرخص بـ28٪ لا بـ30٪.")}],example:n("$1{,}1\\cdot 0{,}9=0{,}99$"),takeaway:e("Kateatuak: indizeak biderkatu, ez ehunekoak batu.","Encadenados: multiplica los índices, no sumes los porcentajes.","المتتالية: اضرب المؤشرات ولا تجمع النسب."),figure:o=>i.jsx(G,{language:o})},{id:"interest",stage:"changes",title:e("Interes bakuna","El interés simple","الفائدة البسيطة"),goal:e("Kapital batek urte batzuetan sortzen duen interes bakuna kalkulatzea.","Calcular el interés simple que produce un capital en unos años.","حساب الفائدة البسيطة التي يُنتجها رأس مال في عدة سنوات."),explanation:e("Bankuan dirua uzten dugunean (kapitala, $C$), bankuak urtero ehuneko bat ordaintzen digu: interes-tasa, $r$. Interes bakunean urte bakoitzeko interesa beti bera da, hasierako kapitalaren % $r$; beraz $t$ urtetan $I=\\frac{C\\cdot r\\cdot t}{100}$. 8000 € % 5ean 3 urtez: $\\frac{8000\\cdot 5\\cdot 3}{100}=1200$ €, eta amaieran $8000+1200=9200$ € ditugu. Mailegu batean berdin, baina guk ordaintzen dugu interesa.","Cuando dejamos dinero en el banco (el capital, $C$), el banco nos paga cada año un porcentaje: el tipo de interés, $r$. En el interés simple el interés de cada año es siempre el mismo, el $r$ % del capital inicial; así que en $t$ años $I=\\frac{C\\cdot r\\cdot t}{100}$. 8000 € al 5 % durante 3 años: $\\frac{8000\\cdot 5\\cdot 3}{100}=1200$ €, y al final tenemos $8000+1200=9200$ €. En un préstamo es igual, pero el interés lo pagamos nosotros.","عندما نودع مالًا في المصرف (رأس المال $C$) يدفع لنا المصرف كل سنة نسبة: سعر الفائدة $r$. وفي الفائدة البسيطة تكون فائدة كل سنة هي نفسها، $r$٪ من رأس المال الأصلي؛ إذن في $t$ سنوات $I=\\frac{C\\cdot r\\cdot t}{100}$. 8000 € بفائدة 5٪ مدة 3 سنوات: $\\frac{8000\\cdot 5\\cdot 3}{100}=1200$ €، وفي النهاية يصبح لدينا $8000+1200=9200$ €. وفي القرض الأمر نفسه، لكننا نحن من يدفع الفائدة."),problem:e("3000 €-ko mailegu bat % 8an hartu eta 2 urtera itzultzen da. Zenbat interes ordaindu behar da?","Se pide un préstamo de 3000 € al 8 % y se devuelve a los 2 años. ¿Cuánto interés hay que pagar?","اقترضنا 3000 € بفائدة 8٪ وسددناها بعد سنتين. كم فائدة يجب دفعها؟"),stepsKind:"steps",steps:[{text:e("Urte bateko interesa.","Interés de un año.","فائدة سنة."),math:n("$3000\\cdot 8\\mathbin{:}100=240$")},{text:e("Bi urtetan.","En dos años.","في سنتين."),math:n("$240\\cdot 2=480$")}],example:n("$I=\\frac{8000\\cdot 5\\cdot 3}{100}=1200$"),takeaway:e("$I=\\frac{C\\cdot r\\cdot t}{100}$; amaierako kapitala $C+I$.","$I=\\frac{C\\cdot r\\cdot t}{100}$; capital final $C+I$.","$I=\\frac{C\\cdot r\\cdot t}{100}$؛ رأس المال النهائي $C+I$."),figure:o=>i.jsx(Q,{language:o})}],ha={table:C,compound:Y,share:W,percent:o=>i.jsx(ea,{...o,modes:Z,challenges:q}),chain:_,interest:N};function fa(o){return i.jsx(v,{...o,tools:u,stages:z,components:ha,title:{eu:"Zuzena, alderantzizkoa ala biak?",es:"¿Directa, inversa o las dos?",ar:"طردي أم عكسي أم كلاهما؟"}})}const xa={storagePrefix:"matella-proportzionaltasuna-dbh2",coursePath:"/matematika/dbh2",courseTitle:{eu:"2. DBH",es:"2.º ESO",ar:"الصف الثاني"},title:{eu:"Proportzionaltasuna eta ehunekoak",es:"Proporcionalidad y porcentajes",ar:"التناسب والنسب المئوية"},documentTitle:{eu:"Proportzionaltasuna eta ehunekoak · 2. DBH",es:"Proporcionalidad y porcentajes · 2.º ESO",ar:"التناسب والنسب المئوية · الصف الثاني"},tagline:{eu:"Igeltseroak, behiak, sariak eta bankua: proportzionaltasun konposatua, banaketak, ehunekoen indizeak eta interesa.",es:"Albañiles, vacas, premios y el banco: proporcionalidad compuesta, repartos, índices de variación e interés.",ar:"البنّاؤون والأبقار والجوائز والمصرف: التناسب المركّب والتوزيعات ومؤشرات التغيّر والفائدة."},heroArt:i.jsx(X,{}),pathSubtitle:{eu:"Bost etapa, proportzioetatik interesera",es:"Cinco etapas, de las proporciones al interés",ar:"خمس مراحل، من التناسبات إلى الفائدة"},stages:z,topics:ga,diagnostic:na,guidedPractice:ia,exerciseBank:sa,challenges:da,lab:{description:{eu:`${u.length} tresna: taula eta grafikoa, proportzionaltasun konposatuaren makina, banaketak, ehunekoak, ehuneko kateatuak eta interesa, erronkekin.`,es:`${u.length} herramientas: tabla y gráfica, máquina de proporcionalidad compuesta, repartos, porcentajes, porcentajes encadenados e interés, con retos.`,ar:`${u.length} أدوات: الجدول والرسم، وآلة التناسب المركّب، والتوزيعات، والنسب المئوية، والنسب المتتالية، والفائدة، مع تحديات.`},progressIds:J,toolForTopic:V,render:o=>i.jsx(fa,{...o})},games:{description:{eu:"Bi joko abiadura eta zehaztasuna entrenatzeko: lasterketa eta memoria.",es:"Dos juegos para entrenar rapidez y precisión: carrera y memoria.",ar:"لعبتان لتدريب السرعة والدقة: السباق والذاكرة."},progressIds:ca,recordsKey:b,render:o=>i.jsx(za,{...o})},answers:{note:{eu:"Idatzi zenbaki bat, komarekin edo puntuarekin (10,8 edo 10.8). Ehunekoetan, idatzi % ikurraren aurreko zenbakia.",es:"Escribe un número, con coma o con punto (10,8 o 10.8). En los porcentajes, escribe el número que va delante del %.",ar:"اكتب عددًا بالنقطة أو بالفاصلة (10.8). وفي النسب المئوية اكتب العدد الذي يسبق ٪."},defaultForm:"any",inputMode:"decimal",normalizeInput:E,placeholder:()=>({eu:"Adib.: 30",es:"Ej.: 30",ar:"مثال: 30"}),wrongForm:()=>({eu:"Balioa zuzena da, baina idatzi zenbaki gisa.",es:"El valor es correcto, pero escríbelo como número.",ar:"القيمة صحيحة، لكن اكتبها عددًا."}),unreadable:{eu:"Ez dut erantzun hori ulertzen. Idatzi zenbaki bat, adibidez 30 edo 10,8.",es:"No entiendo esa respuesta. Escribe un número, por ejemplo 30 o 10,8.",ar:"لم أفهم هذه الإجابة. اكتب عددًا، مثل 30 أو 10.8."}},errorByStage:{proportions:{eu:"Zuzena: zatidura konstantea. Alderantzizkoa: biderkadura konstantea.",es:"Directa: cociente constante. Inversa: producto constante.",ar:"الطردي: حاصل قسمة ثابت. العكسي: حاصل ضرب ثابت."},compound:{eu:"Magnitude bakoitza bere aldetik: zuzena berria/zaharra, alderantzizkoa zaharra/berria.",es:"Cada magnitud por separado: directa nuevo/viejo, inversa viejo/nuevo.",ar:"كل مقدار على حدة: الطردي الجديد/القديم، والعكسي القديم/الجديد."},shares:{eu:"Zuzena: kantitatea : zenbakien batura. Alderantzizkoa: banatu alderantzizkoekiko.",es:"Directo: cantidad : suma de los números. Inverso: reparte a los inversos.",ar:"الطردي: الكمية : مجموع الأعداد. العكسي: وزّع على المقلوبات."},percent:{eu:"% p = p : 100. Osoa = zatia : hamartarra. Ehunekoa = zatia : osoa · 100.",es:"p % = p : 100. Total = parte : decimal. Porcentaje = parte : total · 100.",ar:"p٪ = p : 100. الكل = الجزء : العدد العشري. النسبة = الجزء : الكل · 100."},changes:{eu:"Indizea: 1 ± p : 100. Kateatuak: biderkatu indizeak. I = C · r · t : 100.",es:"Índice: 1 ± p : 100. Encadenados: multiplica los índices. I = C · r · t : 100.",ar:"المؤشر: 1 ± p : 100. المتتالية: اضرب المؤشرات. I = C · r · t : 100."}}};function Ha(){return i.jsx(j,{unit:xa})}export{Ha as ProportzionaltasunaDbh2IntroPage};
